"use strict";(self.webpackChunkallen_blog=self.webpackChunkallen_blog||[]).push([[1477],{30010:n=>{n.exports=JSON.parse('{"blogPosts":[{"id":"/\u53ccWorld\u67b6\u6784\u8be6\u89e3","metadata":{"permalink":"/blog/\u53ccWorld\u67b6\u6784\u8be6\u89e3","source":"@site/blog/\u53ccWorld\u67b6\u6784\u8be6\u89e3.md","title":"\u53ccWorld\u67b6\u6784\u8be6\u89e3\uff1aIsolated World vs Main World","description":"\ud83c\udf0d \u4ec0\u4e48\u662f\\"World\\"\uff1f","date":"2026-04-03T00:00:00.000Z","formattedDate":"April 3, 2026","tags":[{"label":"Chrome\u6269\u5c55","permalink":"/blog/tags/chrome\u6269\u5c55"},{"label":"JavaScript","permalink":"/blog/tags/java-script"},{"label":"Manifest V3","permalink":"/blog/tags/manifest-v-3"},{"label":"Content Script","permalink":"/blog/tags/content-script"}],"readingTime":3.095,"hasTruncateMarker":true,"authors":[{"name":"Allen","url":"https://github.com/ieful","imageURL":"https://avatars.githubusercontent.com/u/138431030?s=96&v=40","key":"Allen"}],"frontMatter":{"title":"\u53ccWorld\u67b6\u6784\u8be6\u89e3\uff1aIsolated World vs Main World","date":"2026-04-03T00:00:00.000Z","authors":"Allen","tags":["Chrome\u6269\u5c55","JavaScript","Manifest V3","Content Script"]},"nextItem":{"title":"Range \u548c Selection","permalink":"/blog/Range"}},"content":"## \ud83c\udf0d \u4ec0\u4e48\u662f\\"World\\"\uff1f\\n\\n\u5728 Chrome \u6269\u5c55\u4e2d\uff0c\\"World\\" \u6307\u7684\u662f JavaScript \u4ee3\u7801\u6267\u884c\u7684**\u4e0a\u4e0b\u6587\u73af\u5883**\u3002\u540c\u4e00\u4e2a\u7f51\u9875\u53ef\u4ee5\u540c\u65f6\u8fd0\u884c\u5728\u591a\u4e2a\u72ec\u7acb\u7684 JavaScript \u4e16\u754c\u4e2d\uff0c\u5b83\u4eec\u4e4b\u95f4\u6709\u4e25\u683c\u7684\u9694\u79bb\u673a\u5236\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \ud83d\udd12 Isolated World\uff08\u9694\u79bb\u4e16\u754c\uff09\\n\\nIsolated World \u662f Chrome \u6269\u5c55 Content Script \u7684**\u9ed8\u8ba4\u6267\u884c\u73af\u5883**\uff0c\u4e0e\u7f51\u9875\u81ea\u8eab\u7684 JavaScript \u4ee3\u7801\u5b8c\u5168\u9694\u79bb\u3002\\n\\n### \u6838\u5fc3\u7279\u6027\\n\\n| \u7279\u6027 | \u8bf4\u660e |\\n|------|------|\\n| \u53d8\u91cf\u9694\u79bb | Content Script \u5b9a\u4e49\u7684\u53d8\u91cf\u4e0d\u4f1a\u6c61\u67d3\u7f51\u9875\u7684\u5168\u5c40\u4f5c\u7528\u57df\uff0c\u53cd\u4e4b\u4ea6\u7136 |\\n| DOM \u5171\u4eab | \u867d\u7136 JS \u73af\u5883\u9694\u79bb\uff0c\u4f46\u4e24\u8005\u64cd\u4f5c\u7684\u662f\u540c\u4e00\u4e2a DOM \u6811 |\\n\\n\u8fd9\u79cd\u8bbe\u8ba1\u7684\u597d\u5904\u662f**\u5b89\u5168\u6027\u9ad8**\u2014\u2014\u6269\u5c55\u4ee3\u7801\u4e0d\u4f1a\u88ab\u7f51\u9875\u7684 JS \u610f\u5916\u8986\u76d6\u6216\u7be1\u6539\u3002\\n\\n## \ud83c\udf10 Main World\uff08\u4e3b\u4e16\u754c\uff09\\n\\nMain World \u662f\u7f51\u9875\u81ea\u8eab JavaScript \u4ee3\u7801\u8fd0\u884c\u7684\u4e0a\u4e0b\u6587\u73af\u5883\uff0c\u4e0e\u7f51\u9875\u7684 JS **\u5b8c\u5168\u5171\u4eab\u540c\u4e00\u4e2a\u4f5c\u7528\u57df**\u3002\\n\\n### \u6838\u5fc3\u7279\u6027\\n\\n| \u7279\u6027 | \u8bf4\u660e |\\n|------|------|\\n| \u53d8\u91cf\u5171\u4eab | \u53ef\u4ee5\u8bfb\u5199\u7f51\u9875\u5b9a\u4e49\u7684\u5168\u5c40\u53d8\u91cf\u3001\u51fd\u6570\u3001\u5bf9\u8c61 |\\n| \u5b8c\u5168\u8bbf\u95ee\u6743\u9650 | \u53ef\u76f4\u63a5\u8bbf\u95ee\u7f51\u9875\u5df2\u52a0\u8f7d\u7684\u7b2c\u4e09\u65b9\u5e93\uff08\u5982 React\u3001jQuery\uff09|\\n| \u5b89\u5168\u98ce\u9669 | \u7f51\u9875\u4ee3\u7801\u53ef\u68c0\u6d4b\u6269\u5c55\u5b58\u5728\uff1b\u53ef\u80fd\u4e0e\u7f51\u9875\u4ee3\u7801\u51b2\u7a81\uff1b\u6613\u88ab\u6076\u610f\u7f51\u9875\u5229\u7528 |\\n\\n## \ud83d\udcdc Manifest V3 \u65b0\u7279\u6027\uff1a`world: \\"MAIN\\"`\\n\\n### \u5386\u53f2\u80cc\u666f\uff1aManifest V2 \u7684\u75db\u70b9\\n\\n\u5728 V2 \u65f6\u4ee3\uff0cContent Script \u53ea\u80fd\u8fd0\u884c\u5728 Isolated World\uff1a\\n\\n```js\\n// manifest.json (V2)\\n{\\n  \\"content_scripts\\": [\\n    {\\n      \\"matches\\": [\\"<all_urls>\\"],\\n      \\"js\\": [\\"content.js\\"]\\n      // \u53ea\u80fd\u5728 Isolated World \u8fd0\u884c\\n    }\\n  ]\\n}\\n```\\n\\n**\u95ee\u9898**\uff1a\u65e0\u6cd5\u76f4\u63a5\u8bbf\u95ee\u7f51\u9875\u7684 JavaScript \u73af\u5883\uff0c\u5fc5\u987b\u901a\u8fc7\u52a8\u6001\u521b\u5efa script \u6807\u7b7e\u7b49 hack \u6280\u5de7\u6765\u7ed5\u8fc7\u9650\u5236\uff0c\u65e2\u7e41\u7410\u53c8\u4e0d\u7a33\u5b9a\u3002\\n\\n### Manifest V3 \u7684\u6539\u8fdb\\n\\nV3 \u65b0\u589e\u4e86 `world` \u5b57\u6bb5\uff0c\u53ef\u4ee5\u76f4\u63a5\u58f0\u660e Content Script \u8fd0\u884c\u5728\u54ea\u4e2a World\uff1a\\n\\n```js\\n// manifest.json (V3)\\n{\\n  \\"content_scripts\\": [\\n    {\\n      \\"matches\\": [\\"<all_urls>\\"],\\n      \\"js\\": [\\"detector.js\\"],\\n      \\"run_at\\": \\"document_start\\"\\n      // \u9ed8\u8ba4 Isolated World\\n    },\\n    {\\n      \\"matches\\": [\\"<all_urls>\\"],\\n      \\"js\\": [\\"detector-main.js\\"],\\n      \\"run_at\\": \\"document_start\\",\\n      \\"world\\": \\"MAIN\\"  // \u65b0\u7279\u6027\uff01\u76f4\u63a5\u8fd0\u884c\u5728\u4e3b\u4e16\u754c\\n    }\\n  ]\\n}\\n```\\n\\n### `world: \\"MAIN\\"` \u7684\u4f18\u52bf\\n\\n**\u5b98\u65b9\u652f\u6301\uff0c\u544a\u522b hack\uff1a**\\n\\n- \u2705 \u4e0d\u518d\u9700\u8981\u52a8\u6001\u521b\u5efa script \u6807\u7b7e\u7b49\u53d8\u901a\u624b\u6bb5\\n- \u2705 \u7b26\u5408\u6d4f\u89c8\u5668\u6269\u5c55\u7684\u6700\u4f73\u5b9e\u8df5\\n- \u2705 \u66f4\u7a33\u5b9a\u3001\u66f4\u53ef\u9760\u3001\u66f4\u6613\u7ef4\u62a4\\n\\n### \u4e24\u79cd World \u7684\u4f7f\u7528\u573a\u666f\u5bf9\u6bd4\\n\\n| \u573a\u666f | \u63a8\u8350 World |\\n|------|-----------|\\n| \u9700\u8981\u8bfb\u5199\u7f51\u9875\u5168\u5c40\u53d8\u91cf | `MAIN` |\\n| \u9700\u8981\u8c03\u7528\u7f51\u9875\u5df2\u52a0\u8f7d\u7684\u7b2c\u4e09\u65b9\u5e93 | `MAIN` |\\n| \u62e6\u622a/\u76d1\u542c\u7f51\u9875\u7684\u51fd\u6570\u8c03\u7528 | `MAIN` |\\n| \u5b89\u5168\u654f\u611f\u64cd\u4f5c\uff08\u5982\u5b58\u50a8 token\uff09| `ISOLATED`\uff08\u9ed8\u8ba4\uff09|\\n| \u4e0e background script \u901a\u4fe1 | `ISOLATED`\uff08\u9ed8\u8ba4\uff09|\\n\\n> \u6765\u81ea\u6653\u5b87\u7684\u9f99\u867e\u52a9\u624b\u5c0f\u7b3c\u5305\ud83e\udd9e"},{"id":"/Range","metadata":{"permalink":"/blog/Range","source":"@site/blog/Range.mdx","title":"Range \u548c Selection","description":"\u6700\u8fd1\u5bf9\u6d4f\u89c8\u5668\u6269\u5c55\u7684\u5f00\u53d1\u5174\u8da3\u9887\u5927\uff0c\u5728\u7740\u624b\u5f00\u53d1\u4e00\u4e2a\u7f51\u9875\u6807\u8bb0\u6269\u5c55\uff0c\u81ea\u5df1\u4e00\u76f4\u7528\u7740\u4e00\u6b3e\u7f51\u9875\u6587\u6863\u6807\u8bb0\u7c7b\u7684\u6269\u5c55\u5de5\u5177","date":"2024-04-06T00:00:00.000Z","formattedDate":"April 6, 2024","tags":[],"readingTime":8.36,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"Range \u548c Selection","date":"2024-04-06T00:00:00.000Z"},"prevItem":{"title":"\u53ccWorld\u67b6\u6784\u8be6\u89e3\uff1aIsolated World vs Main World","permalink":"/blog/\u53ccWorld\u67b6\u6784\u8be6\u89e3"},"nextItem":{"title":"\u8bb0\u5f55\u6700\u8fd1\u505a\u7684\u4e24\u4e2a\u6d4f\u89c8\u5668\uff08Chrome\u5185\u6838\uff09\u6269\u5c55","permalink":"/blog/Chrome\u6269\u5c55"}},"content":"\u6700\u8fd1\u5bf9\u6d4f\u89c8\u5668\u6269\u5c55\u7684\u5f00\u53d1\u5174\u8da3\u9887\u5927\uff0c\u5728\u7740\u624b\u5f00\u53d1\u4e00\u4e2a\u7f51\u9875\u6807\u8bb0\u6269\u5c55\uff0c\u81ea\u5df1\u4e00\u76f4\u7528\u7740\u4e00\u6b3e\u7f51\u9875\u6587\u6863\u6807\u8bb0\u7c7b\u7684\u6269\u5c55\u5de5\u5177\\n\\n\u76ee\u524d\u611f\u89c9\u975e\u5e38\u597d\u7528\u5c31\u662f\u8fd9\u4e2a\u53eb\u505a **Beanote** \u7684\u6269\u5c55\\n\\n\\n<img src=\'/img/Beanote.png\' width={500}/>\\n<br/>\\n\\n\\n\u4e3b\u8981\u529f\u80fd\u5c31\u4e00\u4e2a\uff0c\u53ef\u4ee5\u8ba9\u4f60\u9ad8\u4eae\u6807\u6ce8\u7f51\u9875\u4e2d\u4f60\u8ba4\u4e3a\u91cd\u8981\u7684\u5185\u5bb9\uff0c\u5e76\u652f\u6301\u7ed9\u9ad8\u4eae\u7684\u5730\u65b9\u505a\u5c40\u90e8\u5c0f\u7684\u6ce8\u91ca\u3002\\n\\n<video controls width={600}>\\n    <source src=\'/video/state.mp4\' type=\'video/mp4\'/>\\n</video>\\n<br/>\\n\u867d\u7136\u529f\u80fd\u5f88\u7b80\u5355\uff0c\u4f46\u662f\u611f\u89c9\u5728\u9605\u8bfb\u6587\u6863\u65f6\u8fd8\u662f\u633a\u597d\u7528\u7684\u3002\u6b63\u597d\u81ea\u5df1\u6700\u8fd1\u7684\u5de5\u4f5c\u4e2d\u4e5f\u63a5\u89e6\u5230\u4e86\u6269\u5c55\u7684\u5f00\u53d1\uff0c\\n\\n\u4e8e\u662f\u5c31\u8d81\u7740\u6e05\u660e\u5047\u671f\u60f3\u81ea\u5df1\u5b9e\u73b0\u4e00\u4e2a\u7c7b\u4f3c\u529f\u80fd\u7684\u6269\u5c55\uff0c\u5728\u5199\u4ee3\u7801\u7684\u8fc7\u7a0b\u4e2d\u5b66\u5230\u4e86\u4e00\u4e9b \\"\u51b7\u95e8\uff5e\\" \u7684\u77e5\u8bc6\\n\\n\u5f53\u524d\u8fdb\u5c55\u5982\u4e0b\ud83d\udc47\\n\\n<video controls width={600}>\\n    <source src=\'/video/mynote.mp4\' type=\'video/mp4\'/>\\n</video>\\n<br/>\\n\\n\u76ee\u524d\u7684\u529f\u80fd\u8fd8\u4e0d\u5b8c\u5584\uff0c\u9047\u5230\u6709\u6807\u7b7e\u622a\u65ad\u7684\u60c5\u51b5\u8fd8\u4e0d\u80fd\u5f88\u597d\u7684\u5904\u7406\uff0c\u52aa\u529b\u89e3\u51b3\u4e2d\ud83d\udcaa\u3002\u3002\\n\\n<h6>Range\u7bc7</h6>\\n\\nSelection \u548c Range\u8fd9\u4e2a\u4e24\u4e2a\u6982\u5ff5\u4e3b\u8981\u662f\u8ddf\u9f20\u6807\u5728\u7f51\u9875\u4e0a\u7684\u9009\u4e2d\u4e8b\u4ef6\u76f8\u5173\u7684\uff0c\u5176\u4e2d *Range* \u662f\u4e00\u5bf9\u513f\u4ee3\u8868**\u8fb9\u754c\u70b9**\u8303\u56f4\u7684\u5bf9\u8c61\uff0c\\n\\n\u5176\u5305\u542b\u8303\u56f4\u7684\u8d77\u59cb\u70b9\u548c\u8303\u56f4\u7684\u7ed3\u675f\u70b9\u3002\\n\\n\u521b\u5efa\u4e00\u4e2a Range \u5bf9\u8c61\u8ddf\u521b\u5efa\u5176\u4ed6\u7684JS\u5bf9\u8c61\u4e00\u6837\uff0c\u53ef\u4ee5\u901a\u8fc7\u6784\u9020\u51fd\u6570\u521b\u5efa\\n\\n```js\\nlet range = new Range()\\n```\\n\u7136\u540e\u6211\u4eec\u5c31\u53ef\u4ee5\u901a\u8fc7 **setStart** \u548c **setEnd** \u6765\u5206\u522b\u8bbe\u7f6erange\u5bf9\u8c61\u7684\u8d77\u59cb\u548c\u7ed3\u675f\u8303\u56f4\u4e86\u3002\\n\\n```js\\nlet range = new Range()\\nrange.setStart(node, offset);\\nrange.setEnd(node, offset);\\n```\\n**setStart** \u548c **setEnd** \u90fd\u63a5\u53d7\u4e24\u4e2a\u53c2\u6570\uff0c\u7b2c\u4e00\u4e2a\u53c2\u6570\u53ef\u4ee5\u662f\u6587\u672c\u8282\u70b9\uff08text node\uff09 \u6216\u8005\u662f\u4e00\u4e2a\u5143\u7d20\u8282\u70b9\uff08element node\uff09\uff0c\\n\u8fd9\u4e2a\u5f88\u91cd\u8981\u203c\ufe0f\u56e0\u4e3a\u5b83\u76f4\u63a5\u5f71\u54cd\u4e86\u7b2c\u4e8c\u4e2a\u53c2\u6570\u7684\u542b\u4e49.\\n\\n#### 1\u3001\u6587\u672c\u8282\u70b9\u7684\u60c5\u51b5\\n**\u5982\u679c\u662f\u6587\u672c\u8282\u70b9\uff0c\u90a3\u4e48offset\u4ee3\u8868\u7684\u662f\u6587\u672c\u4e2d\u8df3\u8fc7\u5b57\u7b26\u5143\u7d20\u7684\u4e2a\u6570\uff08\u662f\u8282\u70b9\u4e2d\u7684\u67d0\u4e2a\u4f4d\u7f6e\u5750\u6807\uff09**\\n\\n\u6bd4\u5982\u8bf4\u5143\u7d20 `<p>Hello</p>`\u8981\u521b\u5efa\u4e00\u4e2a\u5305\u542b `ll` \u7684range.\\n```js\\n<p id=\\"p\\">Hello</p>\\n<script>\\n  let range = new Range();\\n  range.setStart(p.firstChild, 2);\\n  range.setEnd(p.firstChild, 4);\\n\\n  // toString of a range returns its content as text\\n  console.log(range); // ll\\n<\/script>\\n```\\n\u6548\u679c\u5982\u4e0b\uff1a\\n![llrange](/img/llrange.png)\\n\\n2\u3001\u5143\u7d20\u8282\u70b9\u7684\u60c5\u51b5\\n\\n**\u5982\u679c\u662f\u5143\u7d20\u8282\u70b9\uff0c\u90a3\u4e48offset \u4ee3\u8868\u7684\u662f\u5176\u8df3\u8fc7\u5b50\u8282\u70b9\u7684\u4e2a\u6570** (\u8fd9\u5bf9\u4e8e\u521b\u5efa\u5305\u542b\u6574\u4e2a\u8282\u70b9\u800c\u4e0d\u662f\u5728\u5176\u6587\u672c\u4e2d\u7684\u67d0\u4e2a\u5730\u65b9\u622a\u65ad\u7684range\u5f88\u65b9\u4fbf\u3002)\\n\\n\u6bd4\u5982\u8bf4\u5bf9\u4e8edom  `<p id=\\"p\\">Example: <i>italic</i> and <b>bold</b></p>`\\n\\n\u5176\u6811\u72b6\u7ed3\u6784\u4e3a\uff1a\\n\\n<img src=\'/img/example.png\' width={500}/>\\n\\n\u5982\u679c\u8981\u6784\u5efa\u4e00\u4e2a `\\"Example: <i>italic</i>\\"` \u8303\u56f4\u7684range \u5e94\u8be5\u5982\u4f55\u8bbe\u7f6e\u5f00\u59cb\u548c\u7ed3\u675f\u70b9\u5462\uff1f\\n\\n\u9996\u5148\u5206\u6790\u5982\u4e0b\uff1a\\n\\n<img src=\'/img/structure.png\' width={500}/>\\n\\n\u8981\u521b\u5efa\u7684range\u7531 `<p>` \u7684\u4e24\u4e2a\u5b50\u8282\u70b9\u7ec4\u6210\uff0c\u4e24\u4e2a\u5b50\u8282\u70b9\u7684index \u5206\u522b\u662f 0 \u548c 1 \u6240\u4ee5\uff1a\\n\\n1\u3001\u8d77\u59cb\u8303\u56f4\u70b9\u7531 *p* \u4f5c\u4e3a\u7236\u8282\u70b9 *0* \u4f5c\u4e3a\u8d77\u59cb\u7684\u504f\u79fb\u91cf  `range.setStart(p, 0)`\\n\\n2\u3001\u7ed3\u675f\u8303\u56f4\u70b9\u540c\u6837\u7531 *p* \u4f5c\u4e3a\u7236\u8282\u70b9\uff0c\u4f46\u662f\u5176\u504f\u79fb\u91cf\u5e94\u8be5\u662f *2* \uff08[) \u5750\u95ed\u53f3\u5f00\u533a\u95f4\uff0cjs\u4e2d\u5f88\u591a\u65b9\u6cd5\u90fd\u662f\u8fd9\u6837\uff0c\u4e0d\u89e3\u91ca\uff09`range.setEnd(p, 2)`\\n\\n:::tip\\n\u5f00\u59cb\u8282\u70b9\u548c\u7ed3\u675f\u8282\u70b9\u53ef\u4ee5\u662f\u4e0d\u540c\u7684\u8282\u70b9\uff0c\u4e00\u4e2arange\u53ef\u4ee5\u8de8\u8d8a\u5f88\u591a\u4e0d\u76f8\u5173\u7684\u8282\u70b9\uff0c\u53ea\u8981\u7ed3\u675f\u8282\u70b9\u5728\u5f00\u59cb\u8282\u70b9\u4e4b\u540e\u5c31\u884c\u4e86\\n:::\\n\\n\u6765\u770b\u4e00\u4e2a\u66f4\u957f\u7684\u8de8\u8d8a\u591a\u4e2a\u8282\u70b9\u7684range\u4f8b\u5b50\uff1a\\n\\n<img src=\'/img/complex.png\' width={500}/>\\n\\n\u8981\u521b\u5efa\u8fd9\u4e2arange \u5e94\u8be5\u5982\u4f55\u8bbe\u7f6e\u5f00\u59cb\u8282\u70b9\u548c\u7ed3\u675f\u8282\u70b9\uff0c\u53ca\u5176\u504f\u79fb\u91cf\u5462\uff1f\\n\\n1\u3001\u9996\u5148\u786e\u5b9a\u5f00\u59cb\u8282\u70b9\u548c\u7ed3\u675f\u8282\u70b9\u662f\u6587\u672c\u8282\u70b9\u8fd8\u662f\u5143\u7d20\u8282\u70b9\uff0c\u7531\u56fe\u53ef\u77e5\u5f00\u59cb\u8282\u70b9\u548c\u7ed3\u675f\u8282\u70b9\u90fd\u5e94\u8be5\u662f\u6587\u672c\u8282\u70b9\uff0c\u56e0\u4e3a range\u5f00\u59cb\u4e8e `Example` \u6587\u672c\u7684\u7b2c\u4e09\u4e2a\u5b57\u6bcd *a* \u7ed3\u675f\u4e8e `bold` \u6587\u672c\u7684\u7b2c\u4e09\u4e2a\u5b57\u6bcd *l*\\n\\n2\u3001\u6839\u636e\u4e0a\u4e00\u6b65\u7684\u5206\u6790\u5206\u522b\u8bbe\u7f6erange\u7684start\u548cend\\n\\n`range.setStart(p.firstChild, 2)`\\n\\n`range.setEnd(p.querySelector(\'b\').firstChild, 3)`\\n\\n#### range \u5bf9\u8c61\u7684\u5c5e\u6027\\n\\n<img src=\'/img/property.png\' width={600}/>\\n\\n\u4e3b\u8981\u6709\u4ee5\u4e0b\u5c5e\u6027\uff1a\\n\\n<ol>\\n    <li>1. startContainer, startOffset \u5f00\u59cb\u8282\u70b9\u548c\u5176\u504f\u79fb\u91cf</li>\\n    <li>2. endContainer, endOffset \u7ed3\u675f\u8282\u70b9\u548c\u5176\u504f\u79fb\u91cf</li>\\n    <li>3. collapsed \u4e00\u4e2a\u5e03\u5c14\u503c\u76f4\u8bd1\u4ee3\u8868\u5f00\u59cb\u8282\u70b9\u548c\u7ed3\u675f\u8282\u70b9\u662f\u5426\u662f\u540c\u4e00\u4f4d\u7f6e\uff0c\u53ea\u8981\u8bb0\u4f4f\u5982\u679c\u8fd9\u4e2a\u503c\u4e3atrue\u5219\u4ee3\u8868range\u662f\u7a7a\uff0c\u5bf9\u5e94\u5230\u9875\u9762\u5c31\u662f\u5565\u90fd\u6ca1\u9009\u4e2d</li>\\n    <li>4. commonAncestorContainer range\u4e2d\u6240\u6709\u8282\u70b9\u7684\u6700\u8fd1\u516c\u5171\u7956\u5148\u8282\u70b9</li>\\n</ol>\\n\\n\\n#### range \u5bf9\u8c61\u7684\u65b9\u6cd5\\n\\n\u9664\u4e86setStart and setEnd \u4e4b\u5916\u8fd8\u6709\u5176\u4ed6\u8f85\u52a9\u7c7b\u7684\u65b9\u6cd5\uff1a\\n\\n<ul>\\n    <li>1. setStartBefore(node) \u5c06start\u8bbe\u7f6e\u5728node\u4e4b\u524d</li>\\n    <li>2. setStartAfter(node) \u5c06start\u8bbe\u7f6e\u5728node\u4e4b\u540e</li>\\n    <li>3. setEndBefore(node) \u5c06end\u8bbe\u7f6e\u5728node\u4e4b\u524d</li>\\n    <li>4. setEndAfter(node) \u5c06end\u8bbe\u7f6e\u5728node\u4e4b\u540e</li>\\n</ul>\\n\\n:::tip\\n\u6240\u6709\u8fd9\u4e9b\u65b9\u6cd5\u4e2d\u7684node\u90fd\u65e2\u53ef\u4ee5\u662f\u6587\u672c\u8282\u70b9\u53c8\u53ef\u4ee5\u662f\u5143\u7d20\u8282\u70b9\uff0c\u540c\u6837\u7684\u5982\u679c\u662f\u6587\u672c\u8282\u70b9\u5219offset\u4ee3\u8868\u6587\u672c\u5b57\u7b26\u7684\u504f\u79fb\u91cf\uff0c\u5982\u679c\u662f\u5143\u7d20\u8282\u70b9\u90a3\u4e48offset\u4ee3\u8868\u7684\u662f\\n\u8df3\u8fc7\u7684\u5b50\u8282\u70b9\u7684\u4e2a\u6570\\n:::\\n\\n\u8fd8\u6709\u4e00\u4e9b\u4e0d\u5e38\u7528\u7684\u521b\u5efarange\u7684\u65b9\u6cd5\uff1a\\n\\n    1. `selectNode(node)`: \u8bbe\u7f6erange\u4e3a\u9009\u4e2d\u6574\u4e2anode\\n    2. `selectNodeContents(node)`: \u8bbe\u7f6erange\u4e3a\u9009\u4e2d\u6574\u4e2anode\u4e2d\u7684\u5185\u5bb9\\n    3. `collapse(toStart)`: \u5982\u679c\u91cc\u9762\u7684 *toStart* \u8bbe\u7f6e\u4e3atrue \u4ee3\u8868end=start/start=end,\u4e5f\u5373collapse\u8bbe\u7f6e\u4e3atrue(rang\u5d29\u6e83 \uff5e)\\n    4. `cloneRange()`: \u514b\u9686\u4e00\u4e2a\u4e00\u6478\u4e00\u6837\u7684range\\n\\n\\n\\n#### range \u5bf9\u8c61\u7684\u7f16\u8f91\u65b9\u6cd5\\n\\n\u5f53\u521b\u5efa\u4e86 range\u5bf9\u8c61\u4e4b\u540e\uff0c\u6211\u4eec\u5c31\u53ef\u4ee5\u5229\u7528\u4e0b\u9762\u8fd9\u4e9b\u65b9\u6cd5\u6765\u64cd\u4f5c\u91cc\u9762\u7684\u5185\u5bb9\u4e86\\n\\n<ol>\\n    <li>deleteContents() \u5c06range\u4e2d\u7684\u5185\u5bb9\u4ece\u6587\u6863\u4e2d\u5220\u9664</li>\\n    <li>extractContents() \u5c06range\u4e2d\u7684\u5185\u5bb9\u79fb\u9664\uff0c\u5e76\u4ee5DocumentFragment\u7684\u5f62\u5f0f\u8fd4\u56de</li>\\n    <li>cloneContents() \u514b\u9686\u4e00\u4e2arange\u4e2d\u7684\u5185\u5bb9\uff0c\u5e76\u4ee5DocumentFragment\u7684\u5f62\u5f0f\u8fd4\u56de</li>\\n    <li>insertNode(node) \u5728range\u7684\u5f00\u5934\u63d2\u5165node</li>\\n    <li>surroundContents(node) <b>\u5728range\u7684\u5185\u5bb9\u5916\u9762\u5305\u88f9\u4e00\u5c42 node</b> \u53ea\u9002\u7528\u4e8e range\u5305\u542b\u5b8c\u6574\u95ed\u5408\u7684\u6807\u7b7e\u7684\u60c5\u51b5 </li>\\n</ol>\\n\\n:::caution\\n\u4e3b\u8981\u662f **surroundContents(node)** \u8fd9\u4e2a\u65b9\u6cd5\u5728\u8bbe\u7f6e\u9009\u4e2d\u6587\u672c\u9ad8\u4eae\u7684\u64cd\u4f5c\u4e2d\u8d77\u5230\u5173\u952e\u6027\u7684\u4f5c\u7528\uff0c\u4f46\u662f\u5176\u9ed8\u8ba4\u53ea\u80fd\u5728\u5305\u542b\u5b8c\u6574\u7684\u6807\u7b7e\u5bf9\u513f\u7684\\n\u60c5\u51b5\u4e0b\u624d\u80fd\u9002\u7528\uff0c\u5982\u679c\u4e00\u4e2arange\u4e2d\u7684\u5185\u5bb9\u53ea\u5305\u542b\u4e86\u67d0\u4e2a\u6807\u7b7e\u7684\u8d77\u59cb\u6807\u7b7e **<** \u6216\u8005 \u95ed\u5408\u6807\u7b7e **</** \u8be5\u65b9\u6cd5\u4f1a\u62a5\u9519\u4e14\u65e0\u6cd5\u6267\u884c\uff0c\u56e0\u6b64\u5bf9\u4e8e\u8fd9\\n\u79cd\u8de8\u6807\u7b7e\u7684\u5904\u7406\u65b9\u5f0f\u9700\u8981\u81ea\u884c\u5904\u7406\uff0c\u4e5f\u662f\u76ee\u524d\u81ea\u5df1\u5728\u7740\u624b\u89e3\u51b3\u7684\u95ee\u9898\u4e4b\u4e00\\n:::\\n\\nRange\u7bc7\u5b8c\uff5e \ud83d\ude29\\n\\n:::tip\\n\u540e\u8bb0\uff1aRange \u8fd4\u56de\u7684\u5c5e\u6027\u4e2d\u6709\u4e00\u4e2a\u53eb\u505a\uff1a*collapsed*, \u8868\u793a\u9009\u533a\u7684\u8d77\u70b9\u4e0e\u7ec8\u70b9\u662f\u5426\u91cd\u53e0\u3002\u5f53 collapsed \u4e3a true\u65f6\uff0c\u8868\u793a\\n\\n**\u9009\u4e2d\u533a\u57df\u88ab\u538b\u7f29\u6210\u4e00\u4e2a\u70b9\uff0c\u5bf9\u4e8e\u666e\u901a\u7684\u5143\u7d20\uff0c\u53ef\u80fd\u4ec0\u4e48\u90fd\u770b\u4e0d\u5230\uff0c\u5982\u679c\u662f\u5728\u53ef\u7f16\u8f91\u7684\u5143\u7d20\u4e0a\uff0c\u90a3\u4e48\u8fd9\u4e2a\u88ab\u538b\u7f29\u7684\u70b9\u5c31\u53d8\u6210\u4e86\u53ef\u4ee5\u95ea\u70c1\u7684\u5149\u6807\uff01**\\n\\n\u6240\u4ee5\uff0c\u5149\u6807\u5c31\u662f\u4e00\u79cd\u8d77\u59cb\u70b9\u548c\u7ed3\u675f\u70b9\u76f8\u540c\u7684\u9009\u533a\uff01\\n:::"},{"id":"/Chrome\u6269\u5c55","metadata":{"permalink":"/blog/Chrome\u6269\u5c55","source":"@site/blog/Chrome\u6269\u5c55.mdx","title":"\u8bb0\u5f55\u6700\u8fd1\u505a\u7684\u4e24\u4e2a\u6d4f\u89c8\u5668\uff08Chrome\u5185\u6838\uff09\u6269\u5c55","description":"\u6269\u5c55\u4e00\uff1a HAR Debugger \u4e00\u4e2a\u53ef\u4ee5\u5e2e\u52a9\u5f00\u53d1\u8005\u5feb\u901f\u5b9a\u4f4d\u5ba2\u6237\u7f51\u7edc\u6216\u8005\u4ea7\u54c1\u95ee\u9898\u7684\u5de5\u5177\u63d2\u4ef6","date":"2024-03-21T00:00:00.000Z","formattedDate":"March 21, 2024","tags":[],"readingTime":16.825,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"\u8bb0\u5f55\u6700\u8fd1\u505a\u7684\u4e24\u4e2a\u6d4f\u89c8\u5668\uff08Chrome\u5185\u6838\uff09\u6269\u5c55","date":"2024-03-21T00:00:00.000Z"},"prevItem":{"title":"Range \u548c Selection","permalink":"/blog/Range"},"nextItem":{"title":"Mobx","permalink":"/blog/Mobx"}},"content":"import HarDemo from \'./HAR\';\\nimport Chat from \'./Chat\';\\nimport Write from \\"./Write\\";\\nimport Gpt from \\"./GPT\\";\\nimport pdf from \'/static/video/pdf.mp4\';\\n\\nimport pdf1 from \'/static/img/pdf1.png\';\\nimport pdf2 from \'/static/img/pdf2.png\';\\nimport pdf3 from \'/static/img/pdf3.png\';\\nimport pdf4 from \'/static/img/pdf4.png\';\\nimport pdf5 from \'/static/img/pdf5.png\';\\n\\n\\n### \u6269\u5c55\u4e00\uff1a HAR Debugger \u4e00\u4e2a\u53ef\u4ee5\u5e2e\u52a9\u5f00\u53d1\u8005\u5feb\u901f\u5b9a\u4f4d\u5ba2\u6237\u7f51\u7edc\u6216\u8005\u4ea7\u54c1\u95ee\u9898\u7684\u5de5\u5177\u63d2\u4ef6\\n\\n\u4ea7\u54c1\u5185\u90e8\u81ea\u6d4b\u901a\u8fc7\uff0c\u4ea4\u4ed8\u7528\u6237\u540e\u5728\u7528\u6237\u7684\u7535\u8111\ud83d\udcbb\u4e0a\u5954\u6e83\u4e86\uff0c\u5ba2\u6237\u6295\u8bc9\u4ea7\u54c1\u5783\u573e\u600e\u4e48\u529e\uff1f\\n\\n#### \u4ec0\u4e48\u662fHAR\u5305\uff1f\\n\\n\u5b9a\u4e49\uff1aHTTP\u5b58\u6863\u683c\u5f0f\uff08HTTP Archive format\uff0c\u7b80\u79f0HAR\uff09\u662f\u4e00\u79cdJSON\u683c\u5f0f\u7684\u5b58\u6863\u6587\u4ef6\u683c\u5f0f\uff0c\u591a\u7528\u4e8e\u8bb0\u5f55\u7f51\u9875\u6d4f\u89c8\u5668\u4e0e\u7f51\u7ad9\u7684\u4ea4\u4e92\u8fc7\u7a0b\u3002\u6587\u4ef6\u6269\u5c55\u540d\u901a\u5e38\u4e3a.har\\n\\n\u201cHAR\u683c\u5f0f\u7684\u89c4\u8303\u5b9a\u4e49\u4e86\u4e00\u4e2aHTTP\u4e8b\u52a1\u7684\u5b58\u6863\u683c\u5f0f\uff0c\u53ef\u7528\u4e8e\u7f51\u9875\u6d4f\u89c8\u5668\u5bfc\u51fa\u52a0\u8f7d\u7f51\u9875\u65f6\u7684\u8be6\u7ec6\u6027\u80fd\u6570\u636e\xa0 \u201d\\t\\t\\t\\t\\t\\t\\t\\t\\t\u2014\u2014Wikipedia\\n\\n\u5982\u4e0b\u6240\u793a\uff1a\u901a\u8fc7\u6539\u6269\u5c55\u53ef\u4ee5\u5e2e\u4f4f\u4f60\u65b9\u4fbf\u5730\u8bb0\u5f55\u5ba2\u6237\u7535\u8111\u4e0a\u4e00\u6bb5\u65f6\u95f4\u53d1\u751f\u7684\u7f51\u7edc\u65f6\u95f4\uff0c\u901a\u8fc7\u751f\u6210\u7684HAR\u5305\u6587\u4ef6\uff0c\u65b9\u4fbf\u5728\u81ea\u5df1\u672c\u5730\u7535\u8111\u590d\u73b0\uff01\ud83e\udd78\uff08\u597d\u5427\uff0c\u6211\u627f\u8ba4\u8fd9\u573a\u666f\u6709\u70b9\u65e0\u804a\ud83e\udd71\uff09\\n<HarDemo></HarDemo>\\n\\n#### \u540e\u8bb0\\n\\n\u5173\u4e8e\u8fd9\u4e2aHAR\u6269\u5c55\u5176\u5b9e\u4e00\u5f00\u59cb\u6211\u662f\u6253\u7b97\u7eaf\u624b\u5de5\u62fc\u63a5\u7684\u65b9\u5f0f\ud83d\udc4b \u628a\u8fd9\u4e2ahar\u7ed9\u6512\u51fa\u6765\u7684\uff0c\u5934\u94c1\u8bd5\u4e86\u4e00\u6bb5\u65f6\u95f4\u53d1\u73b0 **\u81e3\u59be\u505a\u4e0d\u5230\u554a\uff5e\uff5e\ud83d\ude2d**\\n\\n\u91cc\u9762\u6d89\u53ca\u5230\u7684\u5b57\u6bb5\u5f88\u591a\uff0c\u5177\u4f53\u53ef\u4ee5\u67e5\u770b\u8fd9\u4e2a\u94fe\u63a5\ud83d\udd17\uff1a http://www.softwareishard.com/blog/har-12-spec/\\n\\n\u800c\u4e14\u8fd9\u4e9b\u5b57\u6bb5\u90fd\u6765\u81ea\u9875\u9762\u52a0\u8f7d\u8fc7\u7a0b\u4e2d\u7684\u4e0d\u540c\u4e8b\u4ef6\uff0c\u4e14\u4e0d\u5c11\u6709\u4f9d\u8d56\u5173\u7cfb\uff0c\u6211\u7c97\u7565\u7edf\u8ba1\u4e86\u4e00\u4e0b\u81f3\u5c11\u9700\u8981\u76d1\u542c\u4ee5\u4e0b\u8fd9\u4e9b\u4e8b\u4ef6\ud83d\udc47\\n```js\\n[\\n\'Page.loadEventFired\',\\n\'Page.domContentEventFired\',\\n\'Page.frameStartedLoading\',\\n\'Page.frameAttached\',\\n\'Network.requestWillBeSent\',\\n\'Network.requestServedFromCache\',\\n\'Network.dataReceived\',\\n\'Network.responseReceived\',\\n\'Network.resourceChangedPriority\',\\n\'Network.loadingFinished\',\\n\'Network.loadingFailed\',\\n...\\n]\\n```\\n\u6709\u4e9b\u6570\u636e\u7684\u7ec4\u7ec7\u8fc7\u7a0b\u9700\u8981\u8de8\u4e8b\u4ef6\u6765\u6512\uff0c\u867d\u7136\u8bf4\u6bcf\u4e2a\u8bf7\u6c42\u90fd\u6709\u4e00\u4e2arequestId\u6765\u4e32\u8d77\u6765\uff0c\u4f46\u662f\u5176\u4e2d\u7684**\u62fc\u63a5\u89c4\u5219** \u6211\u8fd8\u662f\u62ff\u4e0d\u51c6\ud83d\ude2d\\n\\n\u4e8e\u662f\u5c31\u653e\u5f03\u4e86\u7eaf\u624b\u5de5\u6512\u6570\u636e\u7684\u65b9\u5411\uff0c\u5f00\u59cb\u6c42\u52a9\u793e\u533a\uff0c\u679c\u7136\u5728\u4e07\u80fd\u7684*npm*\u91cc\u88ab\u6211\u53d1\u73b0\u4e86\u8fd9\u4e2a\ud83d\udc49\uff1a[Chrome-har](https://www.npmjs.com/package/chrome-har)\\n\\n\u770b\u8be5package\u7684\u7b80\u4ecb\uff1a\\n\\n    \u201cCreate HAR files based on Chrome DevTools Protocol data.\\n\\n    Code originally extracted from Browsertime,\\n\\n    initial implementation inspired by Chromedriver_har.\u201d\\n\\n\u7b80\u4ecb\u4e2d\u7684\u7b2c\u4e00\u53e5\u8bdd\u6b63\u662f\u6211\u8981\u7684\uff0c\u540e\u9762\u63d0\u5230\u4e86\u53e6\u4e00\u4e2a\u5de5\u5177 **Browsertime** \u6211\u53bb\u770b\u4e86\u4e0b\uff0c\u5f88\u5f3a\u5927\u4e0d\u8fc7\u6211\u7528\u4e0d\u5230\uff5e\uff0c\u611f\u5174\u8da3\u7684\u5c0f\u4f19\u4f34\u53ef\u4ee5\u53bb\u4e86\u89e3\u4e00\u4e0b [Browsertime](https://github.com/sitespeedio/browsertime)\\n\\n*npm install chrome-har* \u76f4\u63a5\u5f00\u641e \u2328\ufe0f\\n\\n```js\\n/*background.js*/\\n\\n// \u9996\u5148\u6211\u5728\u540e\u53f0\u811a\u672c\u7684\u5168\u5c40\u73af\u5883\u4e0b\u521d\u59cb\u5316\u4e86\u51e0\u4e2a\u53d8\u91cf\uff0c\u5206\u522b\u7528\u6765\u8868\u793a\u5f53\u524d\u662f\u5426\u6b63\u5728\u8bb0\u5f55\u7f51\u7edc\u4e8b\u4ef6\u3001\\n// \u5f53\u524d\u901a\u4fe1\u7684tab\u9875\u7b7e\u3001\u7f51\u9875\u540d\u79f0(\u8fd9\u4e2a\u540e\u9762\u7ed9\u751f\u6210\u7684har\u5305\u547d\u540d\u7528)\uff0c\\n// \u4ee5\u53ca\u4e00\u4e2a\u7528\u6765\u4fdd\u5b58\u6536\u96c6\u5230\u7684\u4e8b\u4ef6\u5bf9\u8c61\u7684\u6570\u7ec4\uff0c\u8fd9\u4e2a\u7528\u6765\u201c\u5582\u201d \u7ed9chrome-har \u751f\u6210\u6211\u9700\u8981\u7684\u6587\u4ef6\\nlet recording = false;\\nlet tabId = void 0;\\nlet tabTitle = \'\';\\nlet networkEvents = []; // \u6536\u96c6\u6240\u6709\u7684\u4e8b\u4ef6\u5bf9\u8c61\\n\\n\\n// \u5b9a\u4e49chrome\u6269\u5c55\u7684debugger\u4e8b\u4ef6\u76d1\u542c\u51fd\u6570\\nconst debuggerEventListener = (debuggeeId, method, params) => {\\n    networkEvents.push({method, params}); // \u628a\u76d1\u542c\u5230\u7684\u4e8b\u4ef6\u4e00\u80a1\u8111\u513f\u5168\u653e networkEvents \u91cc\u9762\\n}\\n\\n// \u76d1\u542c\u5f00\u59cb\u7684\u51fd\u6570\uff0c\u9700\u8981\u8c03\u7528chrome.debugger.attach\u65b9\u6cd5\u5c06\u8981\u76d1\u542c\u7684\u7f51\u9875tabId\u7ed1\u5b9a\\n// \u5e76\u5f00\u542f\u5bf9 \'Network.enable\' \u548c \'Page.enable\' \u7cfb\u5217\u4e8b\u4ef6\u7684\u76d1\u542c\\nconst startRecording = () => {\\n    // https://developer.chrome.com/docs/extensions/reference/api/debugger?hl=zh-cn#method-attach\\n    chrome.debugger.attach({ tabId }, \'1.2\', function () {\\n        chrome.debugger.sendCommand({ tabId }, \'Network.enable\', {});\\n        chrome.debugger.sendCommand({tabId}, \'Page.enable\', {}); // page\u4e8b\u4ef6\u5305\u542b\u65f6\u95f4\u4fe1\u606f\uff0c\u9700\u8981\u6dfb\u52a0\u76d1\u542c\\n    });\\n    recording = true;\\n}\\n\\n// \u505c\u6b62\u76d1\u542c\u51fd\u6570\uff0c\u8c03\u7528chrome.debugger.detach \u65b9\u6cd5\u89e3\u9664\u5bf9\u76d1\u542c\u7684\u7f51\u9875\u7684\u7ed1\u5b9a\\nconst stopRecording = () => {\\n    chrome.debugger.detach({tabId}, function () {\\n        recording = false;\\n    })\\n}\\n\\n// \u521d\u59cb\u5316\uff1abackground\u811a\u672c\u521a\u52a0\u8f7d\u4e5f\u5c31\u662f\u6269\u5c55\u521a\u8fdb\u5165\u5de5\u4f5c\u65f6\u6267\u884c\u7684\u4e00\u4e2a\u7ed9\u6269\u5c55icon\u6dfb\u52a0\u4e00\u4e2aOFF\u5b57\u6bb5\uff0c\\n// \u8868\u793a\u672a\u5de5\u4f5c\\nchrome.runtime.onInstalled.addListener(() => {\\n    chrome.action.setBadgeText({\\n        text: \'OFF\' // \u9ed8\u8ba4off\\n    });\\n});\\n\\n// \u5f53\u7528\u6237\u70b9\u51fb\u6269\u5c55icon\u65f6\u5019\u7684\u76d1\u542c\u51fd\u6570\\nchrome.action.onClicked.addListener((tab) => {\\n    tabId = tab.id; // \u8bbe\u7f6etabId\\n    tabTitle = tab.title; // \u8bbe\u7f6etabTitle\\n    chrome.action.getBadgeText({ tabId: tab.id }, function (preState) {\\n        const nextState = preState === \'ON\' ? \'OFF\' : \'ON\'; // \u5207\u6362\u5f53\u524d\u7684\u5de5\u4f5c\u72b6\u6001\u7684\u663e\u793a\\n        chrome.action.setBadgeText({\\n            tabId: tab.id,\\n            text: nextState\\n        });\\n        if (nextState === \'ON\') {\\n            startRecording(); // \u5f00\u542f\u76d1\u542c -> attach\\n            chrome.debugger.onEvent.addListener(debuggerEventListener); // \u76d1\u542c\u56de\u8c03\\n        } else if (nextState === \'OFF\') {\\n            stopRecording(); // \u505c\u6b62\u76d1\u542c -> detach\\n            chrome.debugger.onEvent.removeListener(debuggerEventListener); // \u79fb\u9664\u76d1\u542c\u56de\u8c03\\n            // \u8fd9\u91cc\u6211\u4eec\u628a\u6536\u96c6\u5230\u7684\u4e8b\u4ef6\u505a\u4e86\u4e00\u4e2a\u8fc7\u6ee4\uff0c\u53bb\u9664\u91cc\u9762\u7684Page.frameResized\u4e8b\u4ef6\uff0c\u8fd9\u4e2a\u662f\u8bb0\u5f55\u5f00\u59cb\u65f6\u9876\u90e8\u4f1a\u6709\u4e00\u4e2a\u63d0\u793a\u6269\u5c55\u6b63\u5728\u8c03\u8bd5\u8be5\u9875\u9762\u7684\\n            // \u63d0\u793a\u4fe1\u606f\u5bfc\u81f4\u9875\u9762\u5c3a\u5bf8\u53d1\u751f\u53d8\u52a8\uff0c\u8fd9\u4e2a\u4e8b\u4ef6\u5bf9\u4e8e\u6211\u4eec\u6700\u7ec8\u6536\u96c6\u6570\u636e\u6ca1\u7528\u5f92\u5360\u7a7a\u95f4\uff0c\u56e0\u6b64\u6211\u4eec\u76f4\u63a5\u628a\u5b83\u8fc7\u6ee4\u51fa\u53bb\\n            networkEvents = networkEvents.filter(item => item.method !== \'Page.frameResized\');\\n            // \u5728\u628a\u6536\u96c6\u5230\u7684\u4e8b\u4ef6\u4fe1\u606f\u53d1\u9001\u7ed9\u524d\u53f0\u4e4b\u524d\uff0c\u505a\u4e00\u4e2a\u68c0\u67e5\u270a\\n            if (networkEvents.length) {\\n                // \u5229\u7528chrome.tabs.sendMessage\u6d88\u606f\u901a\u4fe1\u5c06\u540e\u53f0\u6536\u96c6\u5230\u7684\u6570\u636e\u53d1\u9001\u7ed9\u524d\u53f0\\n                chrome.tabs.sendMessage(tabId, {\\n                    type: \'Har\',\\n                    harData: networkEvents,\\n                    name: tabTitle\\n                }, null, (response) => {\\n                    if (response && response.action === \'clear\') {\\n                        networkEvents = [];\\n                    }\\n                })\\n            } else {\\n                alert(\'\u6ca1\u6709\u76d1\u542c\u5230\u4efb\u4f55\u6709\u6548\u6570\u636e\uff0c\u8bf7\u91cd\u65b0\u64cd\u4f5c\u3002\');\\n            }\\n        }\\n    })\\n});\\n\\n```\\n```js\\n/*content.js \u524d\u53f0\u811a\u672c*/\\n\\n// \u5f15\u5165\u6211\u4eec\u5b89\u88c5\u7684chrome-har (\u6ce8\u610f\uff1a\u8fd9\u662f\u4e00\u4e2anode\u5305\uff0c\u6240\u4ee5\u6211\u4eec\u4f7f\u7528commonjs\u7684\u65b9\u5f0frequire\u5f15\u5165)\\nconst { harFromMessages } = require(\'chrome-har\');\\n\\n// \u76d1\u542c\u51fd\u6570\u903b\u8f91\\nconst backgroundListener = (message, sender, sendResponse) => {\\n    // sender.id \u662f\u6269\u5c55\u7684id \\"njjdcblpajfbeljfhfgiielnhgkdmhkn\\"\\n    if (message.type === \'Har\') {\\n        // \u8c03\u7528chrome-har\u5305\u63d0\u4f9b\u7684 harFromMessages \u65b9\u6cd5\u751f\u6210 har\u6587\u4ef6\\n        const har = harFromMessages(message.harData, {includeTextFromResponseBody: true, includeResourcesFromDiskCache: true});\\n        if (!har.log.pages.length || !har.log.entries.length) {\\n            alert(\'\u6ca1\u6709\u76d1\u542c\u5230\u4efb\u4f55\u6709\u6548\u6570\u636e\uff0c\u8bf7\u91cd\u65b0\u64cd\u4f5c\u3002\');\\n        }\\n\\n        // \u4e0b\u9762\ud83d\udc47\u7684\u64cd\u4f5c\u5c31\u662f\u751f\u6210\u5b8char\u5305\u540e\u81ea\u52a8\u4e0b\u8f7d\u23ec\\n        const blob = new Blob([JSON.stringify(har)], {\\n            type: \\"application/json\\",\\n        });\\n        const downloadLink = document.createElement(\'a\');\\n        downloadLink.href = URL.createObjectURL(blob);\\n        downloadLink.download = `${message.name}.har`;\\n        downloadLink.textContent = \'Download HAR\';\\n        document.body.appendChild(downloadLink);\\n        downloadLink.click();\\n        document.body.removeChild(downloadLink);\\n        // \u5b8c\u6210\u4e4b\u540e\u8bb0\u5f97\u901a\u77e5\u540e\u53f0\u811a\u672c\u505a\u3010\u6e05\u7a7a\u3011\u5904\u7406\uff0c\u5426\u5219\u4e0b\u6b21\u8bb0\u5f55\u7f51\u7edc\u4e8b\u4ef6\u4f1a\u5e26\u4e0a\u4e0a\u4e00\u6b21\u7684\u6570\u636e\\n        sendResponse({\\n            action: \'clear\'\\n        })\\n    }\\n}\\n\\n// \u76d1\u542c\u4ece\u540e\u53f0\u4f20\u9012\u8fc7\u6765\u7684\u6d88\u606f\\nchrome.runtime.onMessage.addListener(backgroundListener);\\n\\n```\\n\u7531\u4e8e **chrome-har** \u662f\u4e00\u4e2acommonjs\u683c\u5f0f\u7684node\u5305\uff0c\u56e0\u6b64\u6211\u4eec\u4e0d\u80fd\u6109\u5feb\u7684\u7528vite\u8fdb\u884c\u6784\u5efa\u6253\u5305\u53ea\u80fd\u91cd\u62fewebpack\uff0c\u7b80\u5355\u5199\u4e2a\u914d\u7f6e\u6587\u4ef6 npm run build \u6267\u884c webpack \u8d70\u8d77!\\n\\n```js\\n/*webpack.config.js*/\\n\\nconst path = require(\'path\');\\nmodule.exports = {\\n    entry: \'/src/content.js\',\\n    output: {\\n        filename: \'content.js\',\\n        path: path.resolve(__dirname, \'dist\'),\\n    },\\n};\\n```\\n\u672c\u4ee5\u4e3a\u8fd9\u6837\u5c31\u7ed3\u675f\u4e86\uff0c\u4f46\u662f\u5b89\u88c5\u4e0a\u6269\u5c55\u5230\u6d4f\u89c8\u5668\u8fdb\u884c\u6d4b\u8bd5\u53d1\u73b0\uff0c\u5bfc\u51fa\u7684har\u5305\u4e2d\u8bf7\u6c42\u5934\u3001\u5982\u53c2\u3001url\u3001\u65f6\u95f4\u4fe1\u606f...\u8fd9\u4e9b\u90fd\u6709\uff0c\u552f\u72ec\u6ca1\u6709\u54cd\u5e94\u5b9e\u4f53\u4fe1\u606f\ud83d\ude3a\u3002\u3002\u3002\\n\\n\u8fd9\u4e2a\u4e0d\u5c34\u5c2c\u4e86\u561b\ud83d\ude05\uff0c\u6ca1\u6709\u54cd\u5e94\u6570\u636e\u6211\u770b\u4e2a\u6bdb\u554a\uff0c\u767d\u6298\u817e\u554a\uff0c\u4e8e\u662f\u6211\u8dd1\u5230\u4e86\u4f5c\u8005\u7684github\u4e3b\u9875\uff0c\u53bbissues\u4e2d\u8bd5\u56fe\u5bfb\u627e\u6709\u6ca1\u6709\u7c7b\u4f3c\u95ee\u9898\uff0c\u679c\u7136\u88ab\u6211\u627e\u5230\\n\\n![alt text](/img/harissues1.png)\\n\\n\u8fd9\u4e2aissue\u4e0b\u9762\u6709\u5f88\u591a\u8ba8\u8bba\uff0c\u540e\u9762\u4f5c\u8005\u5728\u4e00\u7cfb\u5217\u7684\u56de\u590d\u4e2d\u8868\u793a\uff0c\u4e0d\u4f1a\u5355\u72ec\u5728chrome-har\u4e2d\u5b9e\u73b0\u8be5\u529f\u80fd\uff0cchrome-har \u5c06\u53ea\u4f1a\u4f5c\u4e3a\u4f7f\u7528\u5df2\u6709\u6570\u636e\u7ec4\u88c5har\u6587\u4ef6\u7684\u7b80\u5355\u5de5\u5177\\n\\n![alt text](/img/harissues2.png)\\n\\n\u7565\u5e26\u4e9b\u8bb8\u6cae\u4e27\u7684\u6211\u65e0\u5948\u6253\u5f00\u4e86chrome-har\u7684\u6e90\u7801\u8fdb\u884c\u67e5\u770b\uff0c\u5728\u5176\u4e2d\u770b\u5230\u8fd9\u6837\u4e00\u884c\u6ce8\u91ca\ud83d\udc40\uff1a\\n\\n![alt text](/img/common.png)\\n\\n\u610f\u601d\u5f88\u660e\u786eresponse.body \u9700\u8981\u6211\u81ea\u5df1\u63d0\u4f9b\uff0c\u5e76\u4e14\u7ed9\u6211\u7529\u51fa\u6765\u4e86\u4e00\u4e2a\u94fe\u63a5 [\ud83d\udd17https://chromedevtools.github.io/devtools-protocol/tot/Network#type-Response](https://chromedevtools.github.io/devtools-protocol/tot/Network#type-Response)\\n\\n\u94fe\u63a5\u6253\u5f00\u76f4\u63a5\u5b9a\u4f4d\u5230\u4e86\u5bf9\u4e8e Network.Response \u7684\u5b57\u6bb5\u89e3\u6790\uff0c\u4ece\u4e2d\u5f97\u8981\u60f3\u62ff\u5230response.body\u6211\u9700\u8981\u81ea\u5df1\u901a\u8fc7 requestId \u4ee5\u5f02\u6b65\u8bf7\u6c42\u7684\u65b9\u5f0f\u83b7\u53d6\u5bf9\u5e94\u7684 Network.Response \u5e76\u4ece\u4e2d\u89e3\u6790\u51fa response.body\\n\\n\u6240\u4ee5\u6211\u7684\u540e\u53f0\u811a\u672c\u4e2d\u9700\u505a\u4fee\u6539\\n\\n```js\\n/*background.js*/\\n\\n// \u4e3b\u8981\u5c31\u662f\u8c03\u6574\u8fd9\u4e2a\u4e8b\u4ef6\u76d1\u542c\u51fd\u6570\u7684\u5904\u7406\u903b\u8f91\uff0c\u4e4b\u524d\u662f\u628a\u6240\u6709\u76d1\u542c\u5230\u7684\u4e8b\u4ef6\u4e0d\u505a\u4efb\u4f55\u5904\u7406\u4e00\u80a1\u8111\u513f\\n// \u76f4\u63a5\u653enetworkEvents\u91cc\u9762\u4e86\uff0c\u73b0\u5728\u9700\u8981\u505a\u7684\u5c31\u662f\u5bf9\u5173\u8054\u54cd\u5e94\u7ed3\u679c\u7684\u4e8b\u4ef6\u5355\u72ec\u505a\u5f02\u6b65\u7684\u8bf7\u6c42\\n// \u5728\u8fd4\u56de\u7684Network.Response \u4e2d\u89e3\u6790\u51fa response.body\\nconst debuggerEventListener = (debuggeeId, method, params) => {\\n    // networkEvents.push({method, params});\\n    if (recording && debuggeeId.tabId === tabId) {\\n      if (method !== \'Network.responseReceived\' && method !== \'Network.dataReceived\') {\\n        networkEvents.push({method, params});\\n      } else {\\n        const requestId = params.requestId;\\n        if (params.response) {\\n          chrome.debugger.sendCommand({ tabId: tabId }, \\"Network.getResponseBody\\", { requestId: requestId }, function (responseBody) {\\n            if (responseBody) {\\n              if (responseBody.body) {\\n                params.response.body = responseBody.body;\\n                networkEvents.push({method, params});\\n              } else {\\n                networkEvents.push({method, params});\\n              }\\n            } else {\\n              console.log(\'\u83b7\u53d6responseBody\u5931\u8d25\');\\n              networkEvents.push({method, params});\\n            }\\n          });\\n        } else {\\n          networkEvents.push({method, params});\\n        }\\n      }\\n    } else {\\n        return;\\n    }\\n}\\n```\\n\u7ecf\u8fc7\u4e00\u6ce2\u4e09\u6298\u7684\u4e00\u756a\u6298\u817e\u540e\u6269\u5c55\u7ec8\u4e8e\u53ef\u4ee5\u6b63\u5e38\u5de5\u4f5c\u4e86\uff0c\u6492\u82b1\ud83c\udf89  \u6269\u5c55\u5df2\u7ecf\u53d1\u5e03\u5230Chrome\u6269\u5c55\u5546\u5e97\uff0c\u641c\u7d22 [HAR Debugger](https://chromewebstore.google.com/search/HAR%20Debugger) \u5373\u53ef\u627e\u5230\u6b22\u8fce\u4e0b\u8f7d\u4f7f\u7528\ud83d\udc4f\\n\\n\\n\\n\\n### \u6269\u5c55\u4e8c\uff1aAI\u667a\u80fd\u52a9\u624b + \u7f51\u9875\u5212\u8bcd\\n\\n\u8fd9\u4e2a\u4e1c\u897f\u6700\u8fd1\u53ef\u662f\u592a\u706b\ud83d\udd25\u4e86\uff0c\u5404\u79cdAI\u52a9\u624b...\u6ee1\u5929\u98de\uff0c\u81ea\u5df1\u4e5f\u505a\u4e86\u4e00\u4e2a\uff0c\u6548\u679c\u5982\u4e0b\uff1a\\n\\n\\n##### \u804a\u5929\u5199\u4f5c\u270f\ufe0f\u80fd\u529b\\n\\n<Chat></Chat>\\n\\n\\n##### \u7f51\u9875\u5212\u8bcd\u7ffb\u8bd1\u80fd\u529b\\n\\n<Write></Write>\\n\\n\u2728\u652f\u6301\u76f4\u63a5\u5728PDF\u4e2d\u5212\u8bcd\u54e6\uff5e\u2728  \u7533\u8bf7\u4e86\u4e13\u5229\u6280\u672f\ud83d\ude09\\n\\n<video src={pdf} controls width={700}/>\\n\\n\u8fd9\u91cc\u662f\u7528\u4e86 Shadowdom \u5c01\u88c5\u4e86\u5143\u7d20\u63d2\u5165\u5230\u6587\u6863\u4e2d\u5b9e\u73b0\u7684\\n\\n```js\\n// \u6269\u5c55\u7684content.js\\nconst injectShadowDom = () => {\\n  const rootElement = document.createElement(\'div\');\\n  rootElement.id = \'aiAssistRoot\';\\n  // \u9632\u6b62\u91cd\u590d\u6ce8\u5165\\n  const rootDom = document.getElementById(\'aiAssistRoot\');\\n  rootDom && rootDom.remove();\\n  // attachShadow to shadowHost\\n  const shadowRoot = rootElement.attachShadow({mode: \'open\'});\\n  let reactContainer = document.createElement(\'div\');\\n  reactContainer.id = \'reactContainer\';\\n  shadowRoot.appendChild(reactContainer);\\n  document.body.appendChild(rootElement);\\n  // \u26a0\ufe0f\u6ce8\u610f\u6211\u4eec\u7684\u6837\u5f0f\u9700\u8981\u901a\u8fc7\u8fd9\u79cd\u65b9\u5f0f\u63d2\u5165\u5230shadowdom\u4e2d\\n  const styleNode = document.createElement(\'style\');\\n  const styleUrl = chrome.runtime.getURL(\'content.css\');\\n  fetch(styleUrl).then(res => res.text()).then(styleData => {\\n    styleNode.textContent = styleData;\\n    shadowRoot.appendChild(styleNode);\\n    // \u4f7f\u7528Antd \u7684 StyleProvider \u5c06antd\u7684\u6837\u5f0f\u4e5f\u63d2\u5165\u5230shadowdom\u4e2d\\n    // <Scribe/> \u5c31\u662f\u6211\u4eec\u9875\u9762\u4e0a\u770b\u5230\u7684\u5212\u8bcd\u548c\u5bf9\u8bdd\u7ec4\u4ef6\u4e86\\n    createRoot(reactContainer).render(\\n        <StyleProvider container={shadowRoot}>\\n          <Scribe/>\\n        </StyleProvider>\\n    )\\n  })\\n}\\n\\ninjectShadowDom();\\n```\\n\\n\u8fd9\u91cc\u9700\u8981\u6ce8\u610f\u63a7\u5236 \u7ec4\u4ef6\u62d6\u62fd\u7684\u65f6\u5019\u4e0d\u8981\u201c\u6ea2\u51fa\u201d\u5c4f\u5e55\u8fb9\u7f18\\n\\n```js\\n// \u62d6\u62fd\u9650\u4f4d\\nlet x = 0;\\nlet y = 0;\\nconst mouseMoveHandler = (e: any) => {\\n    const clientWidth = document.documentElement.clientWidth || document.body.clientWidth;\\n    const clientHeight = document.documentElement.clientHeight || document.body.clientHeight;\\n    const dx = e.clientX - x;\\n    const dy = e.clientY - y;\\n\\n    // \u9650\u4f4d\uff0c\u8fb9\u7f18\u4e0d\u8d85\u51fa\u5c4f\u5e55\\n    if (freeBoxRef.current) {\\n      if (freeBoxRef.current.offsetLeft + dx < 0) {\\n        freeBoxRef.current.style.left = \'0px\'; // \u5de6\u4fa7\u9650\u4f4d\\n      } else if (freeBoxRef.current.offsetLeft + dx > clientWidth - 626) {\\n        freeBoxRef.current.style.left = `${clientWidth - 626}px`; // \u53f3\u4fa7\u9650\u4f4d\\n      } else {\\n        freeBoxRef.current.style.left = `${freeBoxRef.current.offsetLeft + dx}px`; // \u5de6\u53f3\u79fb\u52a8\u8303\u56f4\\n      }\\n      if (freeBoxRef.current.offsetTop + dy < 0) {\\n        freeBoxRef.current.style.top = \'0px\'; // \u9876\u90e8\u9650\u4f4d\\n      } else if (freeBoxRef.current.offsetTop + dy > clientHeight - freeBoxRef.current.offsetHeight) {\\n        freeBoxRef.current.style.top = clientHeight - freeBoxRef.current.offsetHeight > 0 ? `${clientHeight - freeBoxRef.current.offsetHeight}px` : \'0px\'; // \u5e95\u90e8\u9650\u4f4d\\n      } else {\\n        freeBoxRef.current.style.top = `${freeBoxRef.current.offsetTop + dy}px`; // \u4e0a\u4e0b\u6d3b\u52a8\u8303\u56f4\\n      }\\n    }\\n    x = e.clientX;\\n    y = e.clientY;\\n  }\\n```\\n\\n##### \u6539\u7248UI\u52a0\u5165\u5386\u53f2\u5bf9\u8bdd\\n<Gpt></Gpt>\\n\\n#### \u540e\u8bb0\\n\\n\u7f51\u9875\u5212\u8bcd\u8fd9\u90e8\u95e8\u7684\u529f\u80fd\uff0c\u56e0\u4e3a\u6211\u4eec\u5728 *content.js* \u4e2d\u52a0\u5165\u4e86 React \u7ec4\u4ef6\u7684\u521b\u5efa (createRoot) \u6240\u4ee5\uff0ccontent.js\u9700\u8981\u5355\u72ec\u7684\u7f16\u8bd1\u6253\u5305\\n\u5355\u72ec\u7f16\u5199 *vite-content.js*\\n\\n```js\\n/*vite-content.js*/\\nexport default defineConfig({\\n  root: \'src\',\\n  plugins: [\\n    react(),\\n    babel({\\n      babelHelpers: \'bundled\',\\n      exclude: \'node_modules/**\',\\n    })\\n  ],\\n  resolve: {\\n    alias: {\\n      \'@\': path.resolve(__dirname, \'src\')\\n    }\\n  },\\n  // \u26a0\ufe0f\u6ce8\u610fbuild\u7684\u914d\u7f6e\\n  build: {\\n    outDir: \'../dist\',\\n    assetsInlineLimit: 8392,\\n    rollupOptions: {\\n      input: {\\n        \'content\': \'/ext/content.js\' // \u6253\u5305\u5165\u53e3\u8bbe\u7f6e\\n      },\\n      output: {\\n        entryFileNames: \'[name].js\', // \u6253\u5305\u7684\u7ed3\u679c\u9700\u8981\u4fdd\u6301\u6587\u4ef6\u540d\u4e00\u81f4\\n        // \u26a0\ufe0f \u4e0d\u53ef\u4ee5\u4f7f\u7528 iife \u7684\u65b9\u5f0f\uff0ciife \u4f1a\u628a js \u548c css \u90fd\u6253\u5305\u5230\u4e00\u8d77\\n        // format: \'iife\',\\n\\n        // \u914d\u7f6e\u6253\u5305\u51fa\u7684\u5176\u4ed6\u8d44\u6e90\uff0c\u8fd9\u91cc\u5176\u5b9e\u5c31\u662f\u6211\u4eec\u7684\u6837\u5f0f\u4ee3\u7801\uff0c\u547d\u540d\u4e3a content.css\\n        // \u8fd9\u6837\u5c31\u53ef\u4ee5\u901a\u8fc7 const styleUrl = chrome.runtime.getURL(\'content.css\');\\n        // \u7136\u540e fetch(styleUrl).then...\u7684\u65b9\u5f0f\u62ff\u5230\u6211\u4eec\u7684\u6837\u5f0f\u4ee3\u7801\u4e86\\n        assetFileNames: \'content.[ext]\'\\n      }\\n    },\\n  }\\n})\\n```\\n\u53e6\u5916\u6211\u7684\u8bf7\u6c42\u4e5f\u653e\u5230\u540e\u53f0\u811a\u672c *background.js* \u4e2d\u53bb\u4e86\uff0c\u8fd9\u6837\u7528\u6237\u5728\u9875\u9762\u7684 devtools \u7684\u7f51\u7edc\u8bf7\u6c42\u4e2d\u5c31\u4e0d\u4f1a\u770b\u5230\u6269\u5c55\u7684\u8bf7\u6c42\u4e86\\n\u5b9e\u73b0\u66f4\u597d\u7684\u5c01\u88c5\u548c\u9690\u85cf\ud83e\udee5,\u6b64\u65f6\u524d\u53f0\u901a\u8fc7\u4e8b\u4ef6\u89e6\u53d1\u540e\u53f0\u53d1\u8d77\u8bf7\u6c42\uff0c\u518d\u4ece\u540e\u53f0\u63a5\u53d7\u8fd4\u56de\u7684\u54cd\u5e94\u5c31\u9700\u8981\u4e00\u5957\u826f\u597d\u7684\u901a\u4fe1\u673a\u5236\uff0c\u5728Chrome\u6269\u5c55\\n\u4e2d\u4e3b\u8981\u7528\u4e24\u79cd\u901a\u4fe1\u7684\u65b9\u5f0f\uff1a\\n\\n1\u3001chrome.runtime.sendMessage/chrome.tabs.sendMessage \u77ed\u94fe\u63a5\u7684\u65b9\u5f0f\\n\\n2\u3001chrome.runtime.connect/chrome.tabs.connect \u957f\u94fe\u63a5\u7684\u65b9\u5f0f\\n\\n\u77ed\u8fde\u63a5\u7684\u8bdd\u5c31\u662f\u6324\u7259\u818f\u4e00\u6837\uff0c\u6211\u53d1\u9001\u4e00\u4e0b\uff0c\u4f60\u6536\u5230\u4e86\u518d\u56de\u590d\u4e00\u4e0b\uff0c\u5982\u679c\u5bf9\u65b9\u4e0d\u56de\u590d\uff0c\u4f60\u53ea\u80fd\u91cd\u65b0\u53d1\uff0c\u800c\u957f\u8fde\u63a5\u7c7b\u4f3cWebSocket\u4f1a\u4e00\u76f4\u5efa\u7acb\u8fde\u63a5\uff0c\u53cc\u65b9\u53ef\u4ee5\u968f\u65f6\u4e92\u53d1\u6d88\u606f\u3002\\n\\n\u8fd9\u91cc\u5f00\u59cb\u6211\u4f7f\u7528\u7684\u662f\u77ed\u94fe\u63a5\u7684\u65b9\u5f0f\uff0c\u4f46\u662f\u53d1\u73b0\u670d\u52a1\u7aefSSE\u63a8\u9001\u7684\u6570\u636e\u6d41\u8fc7\u6765\u7684\u65f6\u5019\uff0c\u9700\u8981\u4e0d\u65ad\u7684\u89e6\u53d1 sendMessage \u548c onMessage \u7ecf\u5e38\u4f1a\u51fa\u73b0\u6d88\u606f\u9519\u4e71\uff0c\u540c\u4e00\u4e2a\u6d88\u606f\u5185\u5bb9\u91cd\u590d\u591a\u6b21\u7684bug\uff0c\u6539\u6210\u957f\u94fe\u63a5\u7684\u65b9\u5f0f\u5c31\u597d\u4e86\ud83d\udc4c\u3002\\n\\n```js\\n/*content.js\u5411background.js \u53d1\u8d77\u957f\u94fe\u63a5*/\\nconst port = chrome.runtime.connect({name: \\"exampleName\\"}); // \u9700\u8981\u4f20\u9012\u4e00\u4e2a\u5e26name\u7684\u5bf9\u8c61\uff0c\u8fd4\u56de\u4e00\u4e2aport\\n...\\n// \u4e4b\u540e\u5c31\u80fd\u5229\u7528\u8fd9\u4e2aport\u8fdb\u884c\u6d88\u606f\u7684\u53d1\u9001\u548c\u54cd\u5e94\u4e86\\n\\n// \u53d1\u9001\u8bf7\u6c42\\nport.postMessage({\\n  type: \'gptRequest\',\\n  payload: {\\n    params\\n  }\\n});\\n// \u63a5\u53d7\u54cd\u5e94\\nport.onMessage.addListener(msg => {\\n    ...\\n})\\n\\n```\\n\\n```js\\n/*background.js\u4e2d\u76d1\u542c\u6765\u81ea\u524d\u53f0\u7684\u94fe\u63a5\u8bf7\u6c42\u548c\u6d88\u606f*/\\nchrome.runtime.onConnect.addListener(port => {\\n    // \u533a\u5206\u6d88\u606f\u901a\u9053\\n    if (port.name === \'exampleName\') {\\n        port.onMessage.addListener(msg => {\\n            if (msg.type === \'aiRequest\') {\\n                // \u53ef\u4ee5\u5728\u8fd9\u91cc\u53d1\u8d77\u8bf7\u6c42\u4e86\uff0c\u56e0\u4e3a\u670d\u52a1\u7aef\u8fd4\u56de\u7684\u662f\u6d41\u5f0f\u6570\u636e\uff0c\u6240\u4ee5\u6211\u91c7\u7528\u7684fetch\u6765\u5904\u7406\\n                const {params} = msg.payload;\\n                controller = new AbortController(); // \u7ec8\u6b62\u4fe1\u53f7\\n                const {signal} = controller;\\n                requestAi(params, signal).then(res => {\\n                    const reader = res.body?.getReader();\\n                    const decoder = new TextDecoder(\'utf-8\');\\n                    return new ReadableStream({\\n                      start(controller) {\\n                        function push() {\\n                          reader?.read().then(({done, value}) => {\\n                            if (done) {\\n                              port.postMessage({type: \'gptResponseDown\'}); // \u54cd\u5e94\u7ed3\u675f\\n                              return;\\n                            }\\n                            let str = decoder.decode(value);\\n                            if (str.includes(\'error\') && str.includes(\'code\') && !str.startsWith(\'data: \') && !str.includes(\'choices\')) {\\n                              // \u62a5\u9519\\n                              port.postMessage({type: \'gptResponseError\'}); // \u54cd\u5e94\u62a5\u9519\\n                              controller.close();\\n                              return;\\n                            }\\n                            str = str.split(\'\\\\n\')\\n                                .filter((line) => line.startsWith(\'data: \') && line.includes(\'choices\'))\\n                                .map((line) => JSON.parse(line.replace(\'data: \', \'\')).choices[0].delta.content).join(\'\');\\n                            port.postMessage({\\n                              type: \'gptResponseValue\',\\n                              payload: {\\n                                value: str\\n                              }\\n                            });\\n                            controller.enqueue(value);\\n                            push();\\n                          })\\n                        }\\n                        push();\\n                      }\\n                    })\\n                })\\n            } else if (msg.type === \'abortRequest\') {\\n              controller.abort(); // \u4f1a\u62a5\u4e00\u4e2aDOMException\u7684\u5f02\u5e38\u6682\u65f6\u65e0\u6cd5\u6355\u83b7\u5230\u4e0d\u5f71\u54cd\u4e1a\u52a1\ud83e\udd37\u200d\u2640\ufe0f\\n            }\\n        })\\n    }\\n})\\n```\\n\\n### PDF \u5212\u8bcd\u5b9e\u73b0\\n\\nPDF\u4e2d\u5212\u8bcd\u80fd\u529b\u7684\u5b9e\u73b0\u662f\u501f\u52a9\u4e86\u5ba2\u6237\u7aef\u5c01\u88c5\u7684\u65b9\u6cd5\uff0c\u901a\u8fc7\u5728\u6269\u5c55\u4e2d\u76d1\u542c\u6765\u81ea\u5ba2\u6237\u7aef\u7684\u5185\u5bb9\u9009\u4e2d\u4e8b\u4ef6\uff0c\u5e76\u89e3\u6790\u4e8b\u4ef6\u63d0\u4f9b\u7684\u53c2\u6570\u6765\u5b9e\u73b0\u7684\\n\\n\\n<img src={pdf1} alt=\\"pdf1\\"/>\\n\\n<img src={pdf2} alt=\\"pdf2\\"/>\\n\\n<img src={pdf3} alt=\\"pdf3\\"/>\\n\\n<img src={pdf5} alt=\\"pdf5\\"/>\\n\\n<img src={pdf4} alt=\\"pdf4\\"/>"},{"id":"/Mobx","metadata":{"permalink":"/blog/Mobx","source":"@site/blog/Mobx.mdx","title":"Mobx","description":"Flux \u5f00\u7aef","date":"2023-12-27T00:00:00.000Z","formattedDate":"December 27, 2023","tags":[],"readingTime":2.03,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"Mobx","date":"2023-12-27T00:00:00.000Z"},"prevItem":{"title":"\u8bb0\u5f55\u6700\u8fd1\u505a\u7684\u4e24\u4e2a\u6d4f\u89c8\u5668\uff08Chrome\u5185\u6838\uff09\u6269\u5c55","permalink":"/blog/Chrome\u6269\u5c55"},"nextItem":{"title":"Git Remote","permalink":"/blog/Git"}},"content":"### Flux \u5f00\u7aef\\n\\n\u524d\u7aef\u7684\u5f88\u591a\u72b6\u6001\u7ba1\u7406\u5de5\u5177\ud83d\udd27\u90fd\u501f\u9274\u4e86Flux\u7684\u7406\u5ff5\uff0c\u6bd4\u5982\u5927\u5bb6\u7ecf\u5e38\u542c\u5230\u7684**\u5355\u5411\u6570\u636e\u6d41**\u7684\u539f\u5219\u6700\u521d\u5c31\u662f\u7531Flux\u5e26\u5165\u524d\u7aef\u9886\u57df\u7684\uff0c Flux \u662f\u7531 facebook \u56e2\u961f\u63a8\u51fa\u7684\u4e00\u79cd\u67b6\u6784\u7406\u5ff5\uff0c\u5e76\u7ed9\u51fa\u4e00\u4efd\u4ee3\u7801\u5b9e\u73b0\u3002\\n\\n\\n#### \u4e3a\u4ec0\u4e48\u4f1a\u6709 Flux \u7684\u8bde\u751f\uff1f\\n\\nFacebook \u4e00\u5f00\u59cb\u662f\u91c7\u7528\u4f20\u7edf\u7684 MVC \u8303\u5f0f\u8fdb\u884c\u7cfb\u7edf\u7684\u5f00\u53d1\\n\\n![mvc](/img/mvc.png)\\n\\n\u4f46\u968f\u7740\u4e1a\u52a1\u903b\u8f91\u7684\u590d\u6742\uff0c\u6e10\u6e10\u5730\u53d1\u73b0\u4ee3\u7801\u91cc\u8d8a\u6765\u8d8a\u96be\u53bb\u52a0\u5165\u65b0\u529f\u80fd\uff0c\u5f88\u591a\u72b6\u6001\u8026\u5408\u5728\u4e86\u4e00\u8d77\uff0c\u5bf9\u4e8e\u72b6\u6001\u7684\u5904\u7406\u4e5f\u8026\u5408\u5728\u4e86\u4e00\u8d77:\\n\\n![mvcs](/img/mvcs.png)\\n\\n\u9020\u6210\u4e86 FB \u56e2\u961f\u5bf9 MVC \u5410\u69fd\u6700\u6df1\u7684\u4e24\u4e2a\u70b9\uff1a\\n\\n* Controller \u7684\u4e2d\u5fc3\u5316\u4e0d\u5229\u4e8e\u6269\u5c55\uff0c\u6838\u5fc3\u662f\u56e0\u4e3a Controller \u91cc\u9700\u8981\u5904\u7406\u5927\u91cf\u590d\u6742\u7684\u5bf9\u4e8e Model \u66f4\u6539\u7684\u903b\u8f91;\\n* \u5bf9\u4e8e Model \u7684\u66f4\u6539\u53ef\u80fd\u6765\u6e90\u4e8e\u5404\u4e2a\u65b9\u5411\u3002 \u53ef\u80fd\u662f\u5f00\u53d1\u8005\u672c\u8eab\u60f3\u5bf9 Model \u8fdb\u884c\u66f4\u6539\u3001\u53ef\u80fd\u662f View \u4e0a\u7684\u67d0\u4e2a\u56de\u8c03\u60f3\u5bf9 Model \u8fdb\u884c\u66f4\u6539\uff0c\u53ef\u80fd\u662f\u4e00\u4e2a Model \u7684\u66f4\u6539\u5f15\u53d1\u4e86\u53e6\u4e00\u4e2a Model \u7684\u66f4\u6539\u3002\\n\\n\\n\u7531\u4e0a\u56fe\u53ef\u4ee5\u770b\u5230\u51fa\u57fa\u4e8e MVC \u7684\u6570\u636e\u6d41\u5411\u5c31\u6709\u4e09\u79cd\uff1a\\n\\n* Controller -> Model -> View\\n* Controller -> Model -> View -> Model -> View ... (loop)\\n* Controller -> Model1 -> Model2 -> View1 -> view2 ...\\n\\n\u5e76\u4e14\u4e09\u79cd\u6570\u636e\u6d41\u5411\u5728\u5b9e\u9645\u4e1a\u52a1\u4e2d\u8fd8\u5f88\u6709\u53ef\u80fd\u662f\u4ea4\u7ec7\u5728\u4e00\u8d77...\\n\\n\u4e3a\u4e86\u6539\u5584\u4ee5\u4e0a MVC \u5728\u590d\u6742\u5e94\u7528\u4e2d\u7684\u7f3a\u9677\uff0c\u964d\u4f4e\u7cfb\u7edf\u6574\u4f53\u590d\u6742\u5ea6\uff0cFB \u56e2\u961f\u63a8\u51fa\u4e86 Flux \u67b6\u6784\uff0c\u7ed3\u5408 React \u91cd\u6784\u4e86\u4ed6\u4eec\u7684\u4ee3\u7801\uff0c\u8fd9\u5c31\u662f Flux \u67b6\u6784\u8bde\u751f\u7684\u539f\u56e0\u3002"},{"id":"/Git","metadata":{"permalink":"/blog/Git","source":"@site/blog/Git.mdx","title":"Git Remote","description":"Git \u91cc\u9762\u7684 origin \u5230\u5e95\u4ee3\u8868\u5565\u610f\u601d? \u6587\u7ae0\u7531\u6b64\u5c55\u5f00...","date":"2023-12-26T00:00:00.000Z","formattedDate":"December 26, 2023","tags":[],"readingTime":6.55,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"Git Remote","date":"2023-12-26T00:00:00.000Z"},"prevItem":{"title":"Mobx","permalink":"/blog/Mobx"},"nextItem":{"title":"\u6587\u4ef6\u7c7b\u578b\u4e4b\u6587\u672c\u6587\u4ef6\u548c\u4e8c\u8fdb\u5236\u6587\u4ef6","permalink":"/blog/\u6587\u672c\u6587\u4ef6\u548c\u4e8c\u8fdb\u5236\u6587\u4ef6"}},"content":"### Git \u91cc\u9762\u7684 origin \u5230\u5e95\u4ee3\u8868\u5565\u610f\u601d? \u6587\u7ae0\u7531\u6b64\u5c55\u5f00...\\n\\n\u5176\u5b9e **origin** \u5b83\u53ea\u662f\u4e00\u4e2a**\u522b\u540d** \u4ee3\u8868\u7684\u662f **\u8fdc\u7a0bgit\u670d\u52a1\u5668** \u7684\u610f\u601d\u3002\\n\\n\u5047\u8bbe\u516c\u53f8\u6709\u4e00\u4e2a\u5185\u90e8gitlab\u6216gitea\u642d\u5efa\u7684\u670d\u52a1\u5668\uff0c\u5730\u5740\u4e3a\uff1ahttp://192.168.1.100/\\n\\n\u5916\u7f51\u670d\u52a1\u5668\u4e0a\u4e5f\u6709\u4e00\u4e2agit\u670d\u52a1\u5668\uff0c\u5730\u5740\u4e3a\uff1ahttps://git.company.com\\n\\n\u5047\u8bbe\u4f60\u4eec\u5728\u505a\u4e00\u4e2a\u9879\u76ee\u53eb\u201csixsixsix\u201d\uff0c\u4f60\u662f\u9879\u76ee\u8d1f\u8d23\u4eba\uff0c\u4f60\u53ebzhangsan\uff0c\u73b0\u5728\u4f60\u8981\u7ed9\u4f60\u7684\u9879\u76ee\u4e00\u4e2agit\u4ed3\u5e93\u3002\\n\\n\u9996\u5148\uff0c\u4f60\u5728\u672c\u5730\u642d\u597d\u6846\u67b6\uff0c\u9879\u76ee\u6587\u4ef6\u5939\u662fsixsixsix\uff0c\u7136\u540e\u505agit\u7684\u521d\u59cb\u5316\u548c\u63d0\u4ea4\\n\\n```bash\\n    cd sixsixsix\\n    git init\\n    git add .\\n    git commit -m \\"\u9879\u76ee\u8d77\u6b65\uff0c\u9996\u6b21\u63d0\u4ea4\\"\\n```\\n\\n\u597d\u4e86\uff0c\u73b0\u5728\u4f60\u8981\u63a8\u9001\u5230\u5185\u90e8\u670d\u52a1\u5668\uff0c\u8981\u63a8\u9001\u5230\u670d\u52a1\u5668\uff0c\u4f60\u5f97\u5148\u6dfb\u52a0\u5730\u5740\uff0c\u4e0d\u7136git\u600e\u4e48\u77e5\u9053\u8981\u5f80\u54ea\u513f\u63a8\u9001\u5462\uff1f\ud83d\ude02\\n\\n\u6240\u4ee5\u4f60\u8981\u5148\u5728\u5185\u7f51git\u670d\u52a1\u5668\u4e0a\u6dfb\u52a0\u4e00\u4e2a\u4ed3\u5e93\uff0c\u5e76\u628a\u4ed3\u5e93\u5730\u5740\u6dfb\u52a0\u5230\u4f60\u672c\u5730git\u4ed3\u5e93\u4e2d\uff0c\u8fd9\u6837\u4f60push\u7684\u65f6\u5019\uff0cgit\u624d\u77e5\u9053\u5f80\u54ea\u4e2a\u5730\u5740push\\n\\n```bash\\n    git remote add neiwang http://192.168.1.100/zhangsan/sixsixsix.git\\n```\\n\\n\u8fdc\u7a0b\u670d\u52a1\u5668\uff0c\u867d\u7136\u8fd8\u6ca1\u90a3\u4e48\u5feb\u63a8\u9001\uff0c\u4f46\u662f\u8fd8\u662f\u5148\u6dfb\u52a0\u4e00\u4e0b\uff0c\u5148\u628a\u6d41\u7a0b\u8dd1\u901a\uff0c\u514d\u5f97\u8981\u63a8\u9001\u7684\u65f6\u5019\u51fa\u95ee\u9898\\n\\n```bash\\n    git remote add gongwang https://git.company.com/zhangsan/sixsixsix.git\\n```\\n\u597d\u4e86\uff0c\u4f60\u73b0\u5728\u6dfb\u52a0\u4e86\u4e24\u4e2a\u8fdc\u7a0b\u670d\u52a1\u5668\u5730\u5740\u4e86\uff0c\u662f\u65f6\u5019\u63a8\u9001\u4e86\\n\\n\u5148\u5f80\u5185\u90e8\u670d\u52a1\u5668\u63a8\u9001master\u5206\u652f(-u neiwang\u7528\u4e8e\u6307\u5b9a\u5411\u5185\u7f51\u670d\u52a1\u5668\u63a8\u9001\uff09\\n\\n```bash\\n  git push -u neiwang master\\n```\\n\u540e\u671f\u505a\u597d\u4e4b\u540e\uff0c\u5411\u516c\u7f51\u670d\u52a1\u5668\u63a8\u9001\u7a33\u5b9a\u5206\u652f(-u gongwang\u7528\u4e8e\u6307\u5411\u5411\u516c\u7f51\u670d\u52a1\u5668\u63a8\u9001)\\n\\n```bash\\n  git push -u gongwang stable\\n```\\n\\n\u662f\u4e0d\u662f\u53d1\u73b0\uff0c\u8c8c\u4f3c\u8ddf\u5982\u4e0b\u6240\u793a\u7684(\u4f60\u5728csdn\u67e5\u7684)\u547d\u4ee4\u7c7b\u4f3c\uff1f\\n\\n```bash\\n  git push -u origin master\\n```\\n\\n\u5176\u5b9e\u5230\u8fd9\u91cc\u4f60\u5e94\u8be5\u5df2\u7ecf\u660e\u767d\uff0cneiwang\u3001gongwang\u3001origin\u8fd9\u4e09\u4e2a\u5c31\u662f\u4e00\u7c7b\u4e1c\u897f\uff0c\u5c31\u662f\u7528\u6765\u4ee3\u8868\u201c\u8fdc\u7a0b\u4ed3\u5e93\u201d\u7684\uff0c\u5c31\u662f\u540d\u79f0\u4e0d\u4e00\u6837\u800c\u5df2\u3002(git \u9ed8\u8ba4\u751f\u6210\u7684\u5c31\u53eb\u505a\\"origin\\")\\n\\n\u4e8b\u5b9e\u4e0a\uff0c\u63a8\u9001\u5230\u5185\u7f51\u548c\u516c\u7f51\u7684\u547d\u4ee4\u4f60\u8fd8\u53ef\u4ee5\u5199\u6210\u8fd9\u6837:\\n\\n```bash\\n  git push http://192.168.1.100/zhangsan/sixsixsix.git master\\n  git push https://git.company.com/zhangsan/sixsixsix.git stable\\n```\\n\\n:::tip\\n\u5176\u5b9e\u65e0\u8bbaneiwang\u3001gongwang\u3001origin\uff0c\u5b83\u4eec\u53ea\u662f\u8fdc\u7a0b\u670d\u52a1\u5668\u7684\u4e00\u4e2a\u522b\u540d\uff0c\u5426\u5219\u4f60\u5c31\u8981\u5199\u6574\u4e2a\u5730\u5740\uff0c\u663e\u7136\u5199\u6574\u4e2a\u5730\u5740\u592a\u957f\u592a\u9ebb\u70e6\\n:::\\n\\n### \u5185\u90e8\u5b58\u50a8\\n\\n\u6211\u4eec\u5e73\u65f6\u5e38\u7528\u7684git pull\u5c31\u662f\u4e00pull\uff0c\u5c31\u628a\u540c\u4e8b\u7684\u4ee3\u7801\u66f4\u65b0\u4e0b\u6765\u4e86(\u66f4\u65b0\u5230\u5de5\u4f5c\u76ee\u5f55\u4e86)\uff0c\u4f46\u5b9e\u9645\u4e0a\uff0c\u62ff\u5185\u7f51git\u670d\u52a1\u5668\u6765\u8bf4\uff0c\u5982\u679c\u4f60\u4ece\u5185\u7f51git\u670d\u52a1\u5668\u4e0agit pull\u6570\u636e\uff0c\\n\\n\u5b83\u7684\u64cd\u4f5c\u76f8\u5f53\u4e8e\u5148\u7528git fetch\u628a\u6570\u636e\u62c9\u5230\u4f60\u672c\u5730\u9879\u76ee\u4e2d\u7684.git/refs/remotes/neiwang/\u4e0b\u8fb9\u7684master\u5206\u652f\u4e2d\u7684\uff0c\u5982\u679c\u4ece\u5916\u7f51\u4ed3\u5e93\u62c9\u6570\u636e\uff0c\u5b83\u662f\u4f1a\u5148\u4fdd\u5b58\u5230.git/refs/remotes/waiwang/ \u4e0b\u8fb9\u7684stable\u5206\u652f\u4e2d\uff0c\\n\\n\u5f53\u7136\u6211\u4eec\u89c1\u8fc7\u7684\u6700\u591a\u7684\uff0c\u5e94\u8be5\u8fd8\u662f.git/refs/remotes/origin/ \u3002\u540c\u7406\uff0c\u4f60git push\u7684\u65f6\u5019\uff0c\u6570\u636e\u4e5f\u662f\u5148\u5f80.git/refs/remotes/neiwang/\u3001.git/refs/remotes/waiwang/\u3001.git/refs/remotes/origin/\u4e2d\u7684\u5bf9\u5e94\u5206\u652f\u5199\u5165\u7684\\n\\n(\u5f53\u7136\u5199\u5165\u7684\u53ea\u662f\u4e00\u4e2a\u201c\u5f15\u7528\u201d\uff0c\u5177\u4f53\u6570\u636e\u90fd\u5728\u201cobjects\u201d\u6587\u4ef6\u5939\u4e2d)\\n\\n:::info\\n\u5176\u5b9e\u6240\u8c13\u7684\uff1aneiwang\u3001waiwang\u3001origin\uff0c\u90fd\u53ea\u4e0d\u8fc7\u662f.git/refs/remotes/\u4e0b\u7684\u4e00\u4e2a\u6587\u4ef6\u5939\u540d\u79f0\u800c\u5df2\uff0c\\n\u8fd9\u662fgit\u7684\u5de5\u4f5c\u539f\u7406\u51b3\u5b9a\u7684\uff0c.git/refs/remotes/\u4e0b\u7684\u6587\u4ef6\u5939\uff0c\u662f\u8ddf\u8fdc\u7a0b\u4ed3\u5e93\u6570\u636e\u5173\u8054\u7684\uff0c\u53ef\u4ee5\u8ba4\u4e3a\u5b83\u4eec\u662f\u8fdc\u7a0b\u4ed3\u5e93\u5728\u4f60\u672c\u5730\u7684\u7f13\u5b58\uff0c\\n\u5982\u679c\u6ca1\u6709\uff1aneiwang\u3001waiwang\u3001origin\u8fd9\u4e9b\u540d\u79f0\uff0c\u96be\u9053\u8981\u628a\u6587\u4ef6\u5939\u540d\u79f0\u547d\u540d\u4e3a\u6574\u4e2a\u4ed3\u5e93url\u90a3\u4e48\u957f\u5417\uff1f\u663e\u7136\u8fd9\u662f\u4e0d\u53ef\u80fd\u7684\u4e8b\uff01\\n\\n\u8fd9\u4e00\u70b9\u8fd8\u4f53\u73b0\u5728\u4f60\u7684\u672c\u5730\u4ed3\u5e93\u914d\u7f6e\u6587\u4ef6.git/config\u4e2d:\\n\\n```bash\\n    [remote \\"neiwang\\"]\\n        url = https://github.com/zhangsan/sixsixsix.git\\n        fetch = +refs/heads/*:refs/remotes/neiwang/*\\n    [remote \\"waiwang\\"]\\n        url = https://github.com/xiebruce/sixsixsix.git\\n        fetch = +refs/heads/*:refs/remotes/waiwang/*\\n    [branch \\"master\\"]\\n        remote = neiwang\\n        merge = refs/heads/master\\n```\\n:::\\n\\n\\n### git push / git pull \u7684\u5b8c\u6574\u547d\u4ee4\u5f62\u5f0f\\n\\n\\n```bash\\n    Use git push to push commits made on your local branch to a remote repository.\\n\\n    The git push command takes two arguments:\\n\\n    A remote name, for example, origin\\n    A branch name, for example, master\\n    For example:\\n\\n    git push  <REMOTENAME> <BRANCHNAME>\\n\\n    As an example, you usually run $ git push origin master\\n\\n    to push your local changes to your online repository.\\n```\\n\\n\\n```bash\\n    git push [remote] [local_branch]:[remote_branch] # \u5c06\u672c\u5730\u67d0\u5206\u652f\u63a8\u9001\u5230\u8fdc\u7a0b\u67d0\u5206\u652f\\n\\n    git pull [remote] [remote_branch]:[local_brance] # \u5c06\u8fdc\u7a0b\u67d0\u5206\u652f\u62c9\u53d6\u5230\u672c\u5730\u67d0\u5206\u652f\\n```\\n\\n:::tip\\n\u5bf9\u4e8e **git push \u5982\u679c\u672c\u5730\u5206\u652f\u540d\u4e0e\u8fdc\u7a0b\u5206\u652f\u540d\u76f8\u540c\uff0c\u5219\u53ef\u4ee5\u7701\u7565\u5192\u53f7**,\u4f8b\u5982\u628a\u672c\u5730\u7684master\u5206\u652f\u63a8\u52a8\u5230\u8fdc\u7a0bmaster\u5206\u652f\\n\\n\u53ef\u4ee5\u4f7f\u7528  *git push origin master* \u4ee3\u66ff *git push origin master:master*\\n\\n\u5bf9\u4e8e**git pull, \u5982\u679c\u8fdc\u7a0b\u5206\u652f\u662f\u4e0e\u5f53\u524d\u5206\u652f\u5408\u5e76\uff0c\u5219\u5192\u53f7\u540e\u9762\u7684\u90e8\u5206\u53ef\u4ee5\u7701\u7565**, \u4f8b\u5982\u628a\u8fdc\u7a0bmaster\u5206\u652f\u7684\u4ee3\u7801\u5408\u5e76\u5230\u672c\u5730\u7684brantest\u5206\u652f\\n\\n\u53ef\u4ee5\u4f7f\u7528 *git pull origin master* \u4ee3\u66ff *git pull origin master:brantest*\\n:::\\n\\n\\n```bash\\n    git push origin master:master # \u5c06\u672c\u5730\u7684master\u5206\u652f\u63d0\u4ea4\u5230\u8fdc\u7a0b\\n\\n    git push origin master # \u5c06\u672c\u5730\u5f53\u524d\u5206\u652f\u63d0\u4ea4\u5230\u8fdc\u7a0b\\n```\\n\\n\\n:::tip\\n    git pull origin master:brantest\\n\\n    \u5c06\u8fdc\u7a0b\u4e3b\u673aorigin\u7684master\u5206\u652f\u62c9\u53d6\u8fc7\u6765\uff0c\u4e0e\u672c\u5730\u7684brantest\u5206\u652f\u5408\u5e76\u3002\\n\\n    \u540e\u9762\u7684\u5192\u53f7\u53ef\u4ee5\u7701\u7565\uff1a\\n\\n    git pull origin master\\n\\n    \u8868\u793a\u5c06\u8fdc\u7a0borigin\u4e3b\u673a\u7684master\u5206\u652f\u62c9\u53d6\u8fc7\u6765\u548c\u672c\u5730\u7684**\u5f53\u524d\u5206\u652f**\u8fdb\u884c\u5408\u5e76\u3002 (\u5982\u679c\u8fdc\u7a0b\u5206\u652f\u662f\u4e0e\u5f53\u524d\u5206\u652f\u5408\u5e76\uff0c\u5219\u5192\u53f7\u540e\u9762\u7684\u90e8\u5206\u53ef\u4ee5\u7701\u7565)\\n\\n    git push origin HEAD:master  \u8868\u793a\u5c06\u672c\u5730\u5f53\u524dHEAD\u6307\u5411\u5206\u652f\u7684commit\u63d0\u4ea4\u5230\u8fdc\u7a0borigin\u7684master\\n:::\\n\\n\\n\u53c2\u8003\uff1ahttps://www.zhihu.com/question/27712995\\n    https://blog.csdn.net/weixin_41287260/article/details/89743120\\n    https://blog.csdn.net/weixin_44162077/article/details/124598638\\n    https://www.runoob.com/git/git-pull.html\\n    https://www.runoob.com/git/git-push.html"},{"id":"/\u6587\u672c\u6587\u4ef6\u548c\u4e8c\u8fdb\u5236\u6587\u4ef6","metadata":{"permalink":"/blog/\u6587\u672c\u6587\u4ef6\u548c\u4e8c\u8fdb\u5236\u6587\u4ef6","source":"@site/blog/\u6587\u672c\u6587\u4ef6\u548c\u4e8c\u8fdb\u5236\u6587\u4ef6.mdx","title":"\u6587\u4ef6\u7c7b\u578b\u4e4b\u6587\u672c\u6587\u4ef6\u548c\u4e8c\u8fdb\u5236\u6587\u4ef6","description":"\u6982\u8981","date":"2023-12-09T00:00:00.000Z","formattedDate":"December 9, 2023","tags":[],"readingTime":11.795,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"\u6587\u4ef6\u7c7b\u578b\u4e4b\u6587\u672c\u6587\u4ef6\u548c\u4e8c\u8fdb\u5236\u6587\u4ef6","date":"2023-12-09T00:00:00.000Z"},"prevItem":{"title":"Git Remote","permalink":"/blog/Git"},"nextItem":{"title":"JavaScript\u7684\u4e0d\u540c\u683c\u5f0f\u7c7b\u578b","permalink":"/blog/js/format-types"}},"content":"import MyAscii from \'./ascii\';\\r\\n\\r\\n\\r\\n### \u6982\u8981\\r\\n\\r\\n\u672c\u6587\u8bb2\u8ff0\u4ee5\u4e0b\u5185\u5bb9\uff1a\\r\\n\\r\\n* \u6587\u672c\u6587\u4ef6\u548c\u4e8c\u8fdb\u5236\u6587\u4ef6\uff0c\u4e8c\u8005\u7684\u672c\u8d28\u533a\u522b\uff08\u5b58\u50a8\u548c\u4f20\u8f93\uff0c\u4ee5\u53ca\u8868\u793a\uff09\\r\\n* \u4e3a\u4ec0\u4e48\u8981\u8fdb\u884cbase64\u7f16\u7801\uff0c\u4ee5\u53ca\u7f16\u7801\u539f\u7406\\r\\n* \u4ecb\u7ecd\u51e0\u79cd\u5e38\u89c1\u7684/\u7ecf\u5178\u7684\u7f16\u7801\u548c\u5b57\u7b26\u96c6\\r\\n* JS\u4e2d\u7684Blob\u3001Stream\u3001Buffer FormData\u7b49\\r\\n* \u524d\u7aef\u9879\u76ee\u8bf7\u6c42\u5b9e\u4f8b\u5c01\u88c5\u4e2d\u7684\u6587\u4ef6/\u56fe\u7247\u4e0a\u4f20\\r\\n* FileReader\u63a5\u53e3\uff08\u4ee5\u53ca\u4e00\u7cfb\u5217\u7684WebAPI\uff09\\r\\n\\r\\n### \u6587\u4ef6\u7c7b\u578b\\r\\n\\r\\nQ: \u9996\u5148\u4ec0\u4e48\u662f\u6587\u4ef6\uff1f\\r\\n\\r\\nA: \u5728\u8ba1\u7b97\u673a\u4e2d\u6587\u4ef6\u5c31\u662f\u5b58\u50a8\u5728\u67d0\u79cd\u5b58\u50a8\u8bbe\u5907\u4e2d\u7684\u4e00\u6bb5 **\u6570\u636e**\uff0c\u5176\u4f5c\u7528\u5c31\u662f\u5728\u9700\u8981\u7684\u65f6\u5019\u53ef\u4ee5\u53d6\u6765\u4f7f\u7528\u3002\\r\\n\\r\\n\u5728\u8ba1\u7b97\u673a\u4e2d\u6211\u4eec\u901a\u5e38\u5c06\u6587\u4ef6\u5206\u4e3a\u4e24\u79cd\uff0c**\u6587\u672c\u6587\u4ef6** \u548c **\u4e8c\u8fdb\u5236\u6587\u4ef6**\u3002\\r\\n\\r\\n\u6240\u8c13\u6587\u672c\u6587\u4ef6\u6307\u7684\u5c31\u662f\u6211\u4eec\u53ef\u4ee5\u76f4\u63a5\u901a\u8fc7\u6587\u672c\u7f16\u8f91\u5668\uff0c\u6bd4\u5982\u8bb0\u4e8b\u672c\u3001\u5404\u7c7b\u7f16\u7a0b\u5f00\u53d1\u5de5\u5177\u8fdb\u884c\u67e5\u770b\u5176\u5185\u5bb9\u7684\u6587\u4ef6\uff1b\u6587\u672c\u6587\u4ef6\u901a\u5e38\u90fd\u662f\\r\\n\u7ecf\u8fc7\u4e00\u5b9a\u7684\u5b57\u7b26\u7f16\u7801\u7684\uff0c\u6bd4\u5982\u6700\u5e38\u89c1\u7684ASCII\u7f16\u7801\uff0c\u4f46\u5176**\u672c\u8d28\u4f9d\u65e7\u662f\u4e8c\u8fdb\u5236\u6587\u4ef6**\uff0c \u56e0\u4e3a\u5728\u8ba1\u7b97\u673a\u770b\u6765\u6240\u6709\u7684\u6587\u4ef6\u90fd\u662f\u4e8c\u8fdb\u5236\u7684\uff0c\\r\\n\u8ba1\u7b97\u673a\u4e5f\u53ea\u8ba4\u8bc6\u4e8c\u8fdb\u5236\uff080101...\uff09\u3002\u90a3\u6211\u4eec\u4eca\u5929\u8bf4\u7684\u4e8c\u8fdb\u5236\u6587\u4ef6\u5c31\u662f\u76f8\u5bf9\u4e0e\u6587\u672c\u6587\u4ef6\u800c\u8a00\u7684\uff0c\u4e8c\u8fdb\u5236\u6587\u4ef6\u65e0\u6cd5\u901a\u8fc7\u6587\u672c\u7f16\u8f91\u5668\u67e5\u770b\u5176\u5185\u5bb9\uff0c\\r\\n\u800c\u5fc5\u987b\u501f\u52a9\u4e13\u95e8\u7684\u8f6f\u4ef6\u7a0b\u5e8f\u8fdb\u884c\u6253\u5f00\u67e5\u770b\uff0c\u6bd4\u5982\u56fe\u7247\u6587\u4ef6\u9700\u8981\u7528\u56fe\u7247\u67e5\u770b\u5668\u3001\u97f3\u4e50\u6587\u4ef6\u9700\u8981\u7528\u5230\u97f3\u9891\u64ad\u653e\u5668\u3001\u89c6\u9891\u6587\u4ef6\u9700\u8981\u7528\u5230\u89c6\u9891\u64ad\u653e\u5668\u7b49\u7b49..\\r\\n\\r\\n:::info\\r\\n\u6587\u672c\u6587\u4ef6\u662f\u57fa\u4e8e\u5b57\u7b26\u7f16\u7801\u7684\u6587\u4ef6\uff0c\u5e38\u89c1\u7684\u6709ASCII\u3001Unicode\u7b49\uff1b\u4e8c\u8fdb\u5236\u6587\u4ef6\u662f\u57fa**\u4e8e\u503c\u7f16\u7801**\u7684\u6587\u4ef6\uff0c\u53ef\u4ee5\u6839\u636e\u5177\u4f53\u7684\u5e94\u7528\uff0c\u6307\u5b9a\u67d0\u4e2a\u503c\u662f\u4ec0\u4e48\u610f\u601d\uff08\u8fd9\u4e00\u8fc7\u7a0b\uff0c\u53ef\u4ee5\u89c6\u4f5c\u81ea\u5b9a\u4e49\u7f16\u7801\uff0c\u5982\u679c\u4f60\u5b9a\u4e49\u4e86\u81ea\u5df1\u7684\u4e00\u5957\u7f16\u7801\u89c4\u5219\uff0c\u5e76\u80fd\u5c06\u6570\u636e\u6b63\u786e\u7684\u4ee5\u67d0\u79cd\u5f62\u5f0f\u8bfb\u53d6\u51fa\u6765\u5e94\u7528\u7684\u8bdd\uff0c\u90a3\u4e48\u4f60\u5176\u5b9e\u662f\u53d1\u660e/\u521b\u9020\u4e86\u4e00\u79cd\u65b0\u7684\u5e94\u7528\u7a0b\u5e8f\u3002\uff09\\r\\n:::\\r\\n\\r\\n\u6587\u4ef6\u7684\u5b58\u50a8\uff1a\u5728\u8ba1\u7b97\u673a\u7684\u786c\u76d8\u4e2d\u65e0\u8bba\u662f\u6587\u672c\u6587\u4ef6\u8fd8\u662f\u4e8c\u8fdb\u5236\u6587\u4ef6\u90fd\u662f\u4ee5\u5b57\u8282\u8fd9\u79cd\u4e8c\u8fdb\u5236\u5f62\u5f0f\u5b58\u50a8\u7684\uff0c\u5f53\u6587\u4ef6\u88ab\u8bfb\u53d6\u7684\u65f6\u5019\uff0c\u6587\u672c\u6587\u4ef6\u4ece\u5b57\u8282\u6570\u636e\u6309\u7167\u5b57\u7b26\u7f16\u7801\u89c4\u5219\u8f6c\u6362\u6210\u5b57\u7b26\u6570\u636e\uff0c\u4e8c\u8fdb\u5236\u6587\u4ef6\u6bd4\u5982\u56fe\u7247\u4f1a\u6309\u7167\u56fe\u50cf\u7684\u538b\u7f29\u7b97\u6cd5\u3001\u8272\u5f69\u7a7a\u95f4\u7b49\u8fdb\u884c\u56fe\u50cf\u7684\u89e3\u7801\u6700\u7ec8\u5c55\u793a\u5728\u5c4f\u5e55\u4e0a\u3002\\r\\n\\r\\n:::caution\\r\\n\u7f51\u4e0a\u4f3c\u4e4e\u6709\u4e00\u4e2a\u8ff7\u601d\u8bf4\u4e8c\u8fdb\u5236\u6587\u4ef6\u7684\u5b58\u53d6\u6548\u7387\u6bd4\u6587\u672c\u6587\u4ef6\u9ad8\uff1f\u4f46\u662f\u5374\u53c8\u6ca1\u4eba\u80fd\u89e3\u91ca\u6e05\u695a\u4e3a\u4ec0\u4e48\u9ad8\uff0c\u54ea\u4e2a\u9636\u6bb5\u9ad8\u4e86\u3002\u5728\u6211\u770b\u6765\u4e8c\u8fdb\u5236\u6570\u636e\u5c31\u662f\u6570\u636e\u7ed3\u6784\u66f4\u52a0\u7d27\u51d1\u6240\u4ee5\u53ef\u80fd\u66f4\u52a0\u7684\u8282\u7701\u78c1\u76d8\u7a7a\u95f4\uff0c\u5355\u4ece\u5b58\u50a8\u548c\u8bfb\u53d6\u7684\u8fc7\u7a0b\u6765\u770b\uff0c\u4e8c\u8005\u5e76\u6ca1\u6709\u5dee\u522b\uff0c\\r\\n\u7b2c\u4e00\u5b58\u50a8\uff1a\u6587\u672c\u6587\u4ef6\u9700\u8981\u8fdb\u884c\u6587\u672c\u5b57\u7b26\u5230\u4e8c\u8fdb\u5236\u7f16\u7801\u7684\u8fc7\u7a0b\u5b58\u5230\u78c1\u76d8\uff0c\u800c\u4e00\u5f20\u56fe\u7247\u4f60\u5728PS\u4e2d\u7f16\u8f91\u5b8c\u540e\u4fdd\u5b58\u540c\u6837\u4e5f\u6709\u56fe\u50cf\u4fe1\u606f\u8f6c\u6362\u6210\u4e8c\u8fdb\u5236\u7684\u8f6c\u6362\u8fc7\u7a0b\u3002\\r\\n\u7b2c\u4e8c\u8bfb\u53d6\uff1a\u4ece\u78c1\u76d8\u8bfb\u53d6\u4e00\u4e2a\u6587\u672c\u6587\u4ef6\u7684\u4e8c\u8fdb\u5236\u6570\u636e\uff0c\u9700\u8981\u8fdb\u884cASCII\u7f16\u7801\u8f6c\u6362\u6210\u6587\u672c\u5b57\u7b26\u5c55\u793a\uff0c\u800c\u6253\u5f00\u4e00\u5f20\u56fe\u7247\u540c\u6837\u6709\u5b57\u8282\u6570\u636e\u5230\u56fe\u50cf\u4fe1\u606f\u7684\u8f6c\u6362\u8fc7\u7a0b\u3002\\r\\n:::\\r\\n\\r\\n### Base64\u7f16\u7801\\r\\n\\r\\nBase64\u7f16\u7801\u662f\u4ece\u4e8c\u8fdb\u5236\u503c\u5230\u67d0\u4e9b\u7279\u5b9a\u5b57\u7b26\u7684\u7f16\u7801\uff0c\u8fd9\u4e9b\u7279\u5b9a\u5b57\u7b26\u4e00\u517164\u4e2a\uff0c\u6240\u4ee5\u79f0\u4e3aBase64.\\r\\n\\r\\n:::tip\\r\\nQ: \u4e3a\u4ec0\u4e48\u4e0d\u76f4\u63a5\u4f20\u8f93\u4e8c\u8fdb\u5236\u5462\uff0c\u6bd4\u5982\u56fe\u7247\uff08\u5176\u5b9e\u4e5f\u53ef\u4ee5\uff09\u65e2\u7136\u5b9e\u9645\u4f20\u8f93\u65f6\u5b83\u4eec\u90fd\u662f\u4e8c\u8fdb\u5236\u5b57\u8282\u6d41\u3002\u800c\u4e14\u4f7f\u7528Base64\u7f16\u7801\u7684\u8fc7\u7684\u5b57\u7b26\u4e32\u6700\u7ec8\u4e5f\u662f\\r\\n\u4e8c\u8fdb\u5236\u5728\u7f51\u7edc\u4e0a\u4f20\u8f93\uff0c\u90a3\u4e48\u75284/3\u500d\u5e26\u5bbd\u4f20\u8f93\u6570\u636e\u7684Base64\u7a76\u7adf\u6709\u4ec0\u4e48\u610f\u4e49\u5462\uff1f\\r\\n\\r\\nA: \u771f\u6b63\u7684\u539f\u56e0\u662f\u4e3a\u4e86**\u517c\u5bb9**\u3002 \u5728\u7f51\u7edc\u7684\u6574\u4e2a\u4f20\u8f93\u8fc7\u7a0b\u4e2d\u4f1a\u9014\u5f84\u975e\u5e38\u591a\u7684\u4e2d\u95f4\u8bbe\u5907\u3001\u8def\u7531\u5668\u3001\u7f51\u5173\u3001\u96c6\u7ebf\u5668\u3001\u8f6c\u53d1\u5668...\u67d0\u4e9b\u4e8c\u8fdb\u5236\u7684\u503c\uff0c\u5728\u4e00\u4e9b\u786c\u4ef6\u4e0a\u6bd4\u5982\u5728\u4e0d\u540c\u54c1\u724c\u7684\u8def\u7531\u3001\u8001\u7535\u8111\u4e0a\\r\\n\u8868\u793a\u7684\u610f\u4e49\u662f\u4e0d\u4e00\u6837\u7684\uff0c\u505a\u7684\u5904\u7406\u4e5f\u4e0d\u4e00\u6837\u751a\u81f3\u5728\u4e00\u4e9b\u8001\u7684\u8f6f\u4ef6\u7f51\u7edc\u534f\u8bae\u4e0a\u4e5f\u6709\u7c7b\u4f3c\u7684\u95ee\u9898\uff0c\u4f46\u662f\u4e07\u5e78\u7684\u662f\uff0cBase64\u4f7f\u7528\u7684\u8fd964\u4e2a\u5b57\u7b26\u7ecf\u8fc7ASCII/UTF-8\u7f16\u7801\u4e4b\u540e\u5728\u7edd\u5927\u591a\u6570\u673a\u5668\u4e0a\uff0c\u8f6f\u4ef6\u7684\u884c\u4e3a\u662f\u4e00\u81f4\u7684\u3002\\r\\n:::\\r\\n\\r\\n\\r\\n#### ASCII\u7f16\u7801\\r\\n\\r\\nASCII\u7f16\u7801\u603b\u5171**128**\u4e2a\uff0c\u5176\u4e2d\u4e0d\u53ef\u6253\u5370\u5b57\u7b26**33\u4e2a** \uff080 ~ 31 + \u7b2c 127\uff09\uff0c\u53ef\u6253\u5370\u5b57\u7b26**95\u4e2a** \uff0832 ~ 126\uff09\u3002\\r\\n\\r\\n<MyAscii></MyAscii>\\r\\n\\r\\n### \u524d\u7aef\u9879\u76ee\u4e2d\u5c01\u88c5\u8bf7\u6c42\u5b9e\u4f8b\u7684content-type\\r\\n\\r\\n#### \u5148\u8bf4\u7ed3\u8bba\\r\\n\\r\\n1\u3001Post\u8bf7\u6c42\u7b80\u5355\u8868\u5355\u6570\u636e\uff1a**Content-Type: application/x-www-form-urlencoded**\\r\\n\\r\\n:::info\\r\\n\u901a\u5e38\u88ab\u7528\u4e8eHTML\u8868\u5355\u63d0\u4ea4\uff0c\u6570\u636e\u4f1a\u88ab\u7f16\u7801\u6210\u952e\u503c\u5bf9\u7684\u5f62\u5f0f\\r\\n:::\\r\\n\\r\\n2\u3001Post\u8bf7\u6c42\uff0cJSON\u6570\u636e\uff1a**Content-Type: application/json**\\r\\n\\r\\n:::info\\r\\n\u5f53\u901a\u8fc7 POST \u8bf7\u6c42\u53d1\u9001 JSON \u683c\u5f0f\u7684\u6570\u636e\u65f6\uff0c\u5e94\u8be5\u4f7f\u7528\u8fd9\u4e2a Content-Type\u3002\u8fd9\u5728\u73b0\u4ee3 Web \u5f00\u53d1\u4e2d\u5f88\u5e38\u89c1\uff0c\u7279\u522b\u662f\u4e0e RESTful API \u4e00\u8d77\u4f7f\u7528\\r\\n:::\\r\\n\\r\\n3\u3001POST\u8bf7\u6c42\uff0c\u6587\u4ef6\u4e0a\u4f20\uff1a**Content-Type: application/form-data**\\r\\n\\r\\n:::info\\r\\n\u7528\u4e8e\u901a\u8fc7 POST \u8bf7\u6c42\u4e0a\u4f20\u6587\u4ef6\u3002\u5e38\u7528\u4e8e\u8868\u5355\u4e2d\u5305\u542b\u6587\u4ef6\u4e0a\u4f20\u7684\u573a\u666f\\r\\n:::\\r\\n\\r\\n4\u3001POST\u8bf7\u6c42\uff0c\u7eaf\u6587\u672c\u6570\u636e\uff1a**Content-Type: text/plain**\\r\\n\\r\\n:::info\\r\\n\u7528\u4e8e\u53d1\u9001\u7eaf\u6587\u672c\u6570\u636e\u3002\\r\\n:::\\r\\n\\r\\n5\u3001Get\u8bf7\u6c42\uff0c\u4e00\u822c\u4e0d\u5305\u542b\u8bf7\u6c42\u4f53\uff0c\u4f46\u662f\u5982\u679c\u5305\u542b\u4e86\u4e00\u822c\u4f7f\u7528 **Content-Type: application/x-www-form-urlencoded** \u6216\u8005 **Content-Type: text/plain**\\r\\n\\r\\n6\u3001XML \u6570\u636e\uff1a**Content-Type: application/xml**, \u5f53\u9700\u8981\u53d1\u9001\u6216\u63a5\u6536 XML \u6570\u636e\u65f6\u4f7f\u7528.\\r\\n\\r\\n:::tip\\r\\nContent-Type \u65e2\u53ef\u4ee5\u51fa\u73b0\u5728\u8bf7\u6c42\u5934\u4e2d\uff0c\u4e5f\u53ef\u4ee5\u51fa\u73b0\u5728\u54cd\u5e94\u5934\u4e2d\u3002\u5728 HTTP \u534f\u8bae\u4e2d\uff0cContent-Type \u662f\u7528\u6765\u6307\u793a\u5b9e\u4f53\u6b63\u6587\u7684\u5a92\u4f53\u7c7b\u578b\u7684\u6807\u5934\u5b57\u6bb5\u3002\\r\\n\\r\\n\u56e0\u6b64\uff0cContent-Type \u662f\u4e00\u4e2a\u5e38\u89c1\u7684\u8bf7\u6c42\u5934\u548c\u54cd\u5e94\u5934\u5b57\u6bb5\uff0c\u7528\u4e8e\u786e\u4fdd\u53d1\u9001\u548c\u63a5\u6536\u7684\u6570\u636e\u4ee5\u6b63\u786e\u7684\u683c\u5f0f\u8fdb\u884c\u89e3\u6790\u3002\u5728\u8bf7\u6c42\u5934\u4e2d\uff0c\u5b83\u544a\u8bc9\u670d\u52a1\u5668\u8bf7\u6c42\u6b63\u6587\u7684\u683c\u5f0f\uff0c\u800c\u5728\u54cd\u5e94\u5934\u4e2d\uff0c\u5b83\u544a\u8bc9\u5ba2\u6237\u7aef\u8fd4\u56de\u6570\u636e\u7684\u683c\u5f0f\u3002\\r\\n:::\\r\\n\\r\\n#### \u5173\u4e8e responseType\\r\\n\\r\\n**responseType** \u662f*Fetch API* \u4e2d\u8bf7\u6c42\u914d\u7f6e\u5bf9\u8c61\u7684\u4e00\u4e2a\u5c5e\u6027\uff0c\u56e0\u6b64\u4ed6\u662f**\u8bf7\u6c42\u5934**\u7684\u4e00\u90e8\u5206\uff0c\u7528\u4e8e\u6307\u5b9a\u670d\u52a1\u5668\u54cd\u5e94\\r\\n\u7684\u6570\u636e\u7c7b\u578b\u3002**axios** \u662f\u4e00\u4e2a\u57fa\u4e8e*Promise*\u7684http\u5ba2\u6237\u7aef\u5e93\uff0c\u5b83\u5728\u4f7f\u7528\u4e0a\u5f88\u7c7b\u4f3c\u4e8eFetch API\uff0c\u5e76\u4e14\u4e5f\u63d0\u4f9b\u4e86\u7c7b\u4f3c\u7684\\r\\n\u914d\u7f6e\u9879\u5176\u4e2d\u5305\u62ec*responseType*.\\r\\n\\r\\n\u53ef\u4ee5\u901a\u8fc7\u914d\u7f6e*responseType*\u6765\u544a\u8bc9\u6d4f\u89c8\u5668\u5e0c\u671b\u4ee5\u4ec0\u4e48\u6837\u7684\u6570\u636e\u7c7b\u578b\u6765\u5904\u7406\u670d\u52a1\u5668\u54cd\u5e94\u3002\u4ee5\u4e0b\u662f\u4e00\u4e9b\u5e38\u89c1\u7684*responseType*\u503c\\r\\n\\r\\n1\u3001**responseType: \'text\'** \u5c06\u54cd\u5e94\u89e3\u6790\u4e3a\u6587\u672c\u5b57\u7b26\u4e32\\r\\n\\r\\n2\u3001**responseType: \'json\'** \u5c06\u54cd\u5e94\u89e3\u6790\u4e3aJSON\u5bf9\u8c61\\r\\n\\r\\n3\u3001**responseType: \'blob\'** \u5c06\u54cd\u5e94\u89e3\u6790\u4e3a\u4e8c\u8fdb\u5236\u6570\u636e\uff08Blob\u5bf9\u8c61\uff09\\r\\n\\r\\n4\u3001**responseType: \'arraybuffer\'** \u5c06\u54cd\u5e94\u89e3\u6790\u4e3a\u4e8c\u8fdb\u5236\u5bf9\u8c61\uff08ArrayBuffer\u5bf9\u8c61\uff09\\r\\n\\r\\n5\u3001**responseType: \'document\'** \u5c06\u54cd\u5e94\u89e3\u6790\u4e3aXML\u6587\u6863\uff08\u53ef\u4ee5\u662fXML\u3001HTML\u7b49\uff09\\r\\n\\r\\n6\u3001**responseType: \'stream\'** \u7528\u4e8e\u5c06\u54cd\u5e94\u6570\u636e\u4ee5**Node.js** \u53ef\u8bfb\u6d41\u7684\u5f62\u5f0f\u8fd4\u56de\u3002\u8fd9\u79cd\u5f62\u5f0f\u5bf9\u4e8e\u5904\u7406\u5927\u578b\u54cd\u5e94\u6570\u636e\u6216\u5b9e\u65f6\u6570\u636e\u6d41\u975e\u5e38\u6709\u7528\uff01\\r\\n\\r\\n### FileReader\\r\\n\\r\\n**FileReader** \u5bf9\u8c61\u5141\u8bb8Web\u5e94\u7528\u7a0b\u5e8f\u5f02\u6b65\u8bfb\u53d6\u5b58\u50a8\u5728\u7528\u6237\u8ba1\u7b97\u673a\u4e0a\u7684\u6587\u4ef6\uff08\u6216\u539f\u59cb\u6570\u636e\u7f13\u5b58\u533a\uff09\u7684\u5185\u5bb9\uff0c\u4f7f\u7528**File** \u6216\u8005**Blob** \u5bf9\u8c61\u6307\u5b9a\u8981\u8bfb\u53d6\u7684\u6587\u4ef6\u6216\u6570\u636e\u3002\\r\\n\\r\\n\u5176\u4e2d File \u5bf9\u8c61\u53ef\u4ee5\u662f\u6765\u81ea\u7528\u6237\u5728\u4e00\u4e2ainput\u5143\u7d20\u4e0a\u9009\u62e9\u6587\u4ef6\u540e\u8fd4\u56de\u7684FileList\u5bf9\u8c61\uff0c\u4e5f\u53ef\u4ee5\u6765\u81ea\u62d6\u653e\u64cd\u4f5c\u751f\u6210\u7684 DataTransfer\u5bf9\u8c61\uff0c\u8fd8\u53ef\u4ee5\u662f\u6765\u81ea\u5728\u4e00\u4e2aHTMLCanvasElement\u4e0a\u6267\u884cmozGetAsFile()\u65b9\u6cd5\u540e\u8fd4\u56de\u7ed3\u679c\u3002\\r\\n\\r\\n:::info\\r\\nFile\u5bf9\u8c61\u53ef\u4ee5\u770b\u4f5c\u4e00\u79cd\u7279\u6b8a\u7684Blob\u5bf9\u8c61. Blob\u662fFile\u7684\u7236\u7c7b\u3002\\r\\n:::\\r\\n\\r\\n#### \u65b9\u6cd5\\r\\n\\r\\n1\u3001FileReader.readAsArrayBuffer(): \u5f00\u59cb\u8bfb\u53d6\u6307\u5b9a\u7684 Blob\u4e2d\u7684\u5185\u5bb9\uff0c\u4e00\u65e6\u5b8c\u6210\uff0cresult \u5c5e\u6027\u4e2d\u4fdd\u5b58\u7684\u5c06\u662f\u88ab\u8bfb\u53d6\u6587\u4ef6\u7684 ArrayBuffer \u6570\u636e\u5bf9\u8c61\u3002\\r\\n\\r\\n2\u3001FileReader.readAsDataURL(): \u5f00\u59cb\u8bfb\u53d6\u6307\u5b9a\u7684Blob\u4e2d\u7684\u5185\u5bb9\u3002\u4e00\u65e6\u5b8c\u6210\uff0cresult\u5c5e\u6027\u4e2d\u5c06\u5305\u542b\u4e00\u4e2adata: URL \u683c\u5f0f\u7684 Base64 \u5b57\u7b26\u4e32\u4ee5\u8868\u793a\u6240\u8bfb\u53d6\u6587\u4ef6\u7684\u5185\u5bb9\u3002\\r\\n\\r\\n3\u3001FileReader.readAsText(): \u5f00\u59cb\u8bfb\u53d6\u6307\u5b9a\u7684Blob\u4e2d\u7684\u5185\u5bb9\u3002\u4e00\u65e6\u5b8c\u6210\uff0cresult\u5c5e\u6027\u4e2d\u5c06\u5305\u542b\u4e00\u4e2a\u5b57\u7b26\u4e32\u4ee5\u8868\u793a\u6240\u8bfb\u53d6\u7684\u6587\u4ef6\u5185\u5bb9\u3002\\r\\n\\r\\n:::tip\\r\\n\u5f53\u6211\u4eec\u9700\u8981\u8bfb\u53d6\u4e00\u4e2a\u6587\u4ef6\u7684\u65f6\u5019\uff0c\u5982\u679c\u662f\u6587\u672c\u6587\u4ef6\u6211\u4eec\u5c31\u53ef\u4ee5\u901a\u8fc7 let fr = new FileReader(); fr.readAsText(\'\u6587\u4ef6\') \u65b9\u6cd5\u6765\u8bfb\u53d6\u6587\u4ef6\u5185\u5bb9\uff1b\\r\\n\u800c\u5f53\u6587\u4ef6\u662f\u4e00\u4e2a\u4e8c\u8fdb\u5236\u6587\u4ef6\u7684\u65f6\u5019\uff0c\u6211\u4eec\u5c31\u53ef\u4ee5\u901a\u8fc7fr.readAsArrayBuffer(\'\u6587\u4ef6\')\u6765\u8bfb\u53d6\u6587\u4ef6\u5185\u5bb9\u3002\\r\\n:::\\r\\n\\r\\n```javascript\\r\\n// \u8bfb\u53d6\u6587\u672c\u6587\u4ef6\uff1a\\r\\n\\r\\n    // \u521b\u5efa FileReader \u5bf9\u8c61\\r\\n    const reader = new FileReader();\\r\\n\\r\\n    // \u4e3a FileReader \u8bbe\u7f6e onload \u4e8b\u4ef6\u5904\u7406\u7a0b\u5e8f\\r\\n    reader.onload = function(event) {\\r\\n      // event.target.result \u5305\u542b\u6587\u4ef6\u7684\u6587\u672c\u5185\u5bb9\\r\\n      console.log(event.target.result);\\r\\n    };\\r\\n\\r\\n    // \u8bfb\u53d6\u6587\u672c\u6587\u4ef6\\r\\n    const fileInput = document.getElementById(\'fileInput\'); // \u5047\u8bbe\u6709\u4e00\u4e2a input \u5143\u7d20\u7528\u4e8e\u9009\u62e9\u6587\u4ef6\\r\\n    const selectedFile = fileInput.files[0];\\r\\n    reader.readAsText(selectedFile);\\r\\n\\r\\n// \u8bfb\u53d6\u56fe\u50cf\u6587\u4ef6\u5e76\u663e\u793a\uff1a\\r\\n\\r\\n    const reader = new FileReader();\\r\\n\\r\\n    reader.onload = function(event) {\\r\\n      // event.target.result \u5305\u542b\u56fe\u50cf\u6587\u4ef6\u7684 data URL\\r\\n      const imgElement = document.getElementById(\'imageElement\'); // \u5047\u8bbe\u6709\u4e00\u4e2a img \u5143\u7d20\u7528\u4e8e\u663e\u793a\u56fe\u50cf\\r\\n      imgElement.src = event.target.result;\\r\\n    };\\r\\n\\r\\n    const fileInput = document.getElementById(\'fileInput\'); // \u5047\u8bbe\u6709\u4e00\u4e2a input \u5143\u7d20\u7528\u4e8e\u9009\u62e9\u6587\u4ef6\\r\\n    const selectedFile = fileInput.files[0];\\r\\n    reader.readAsDataURL(selectedFile);\\r\\n\\r\\n// \u8bfb\u53d6\u4e8c\u8fdb\u5236\u6587\u4ef6\uff08\u4f8b\u5982\uff0cArrayBuffer\uff09\uff1a\\r\\n\\r\\n    const reader = new FileReader();\\r\\n\\r\\n    reader.onload = function(event) {\\r\\n      // event.target.result \u5305\u542b\u4e8c\u8fdb\u5236\u6587\u4ef6\u7684 ArrayBuffer\\r\\n      const arrayBuffer = event.target.result;\\r\\n      // \u5904\u7406 ArrayBuffer\\r\\n    };\\r\\n\\r\\n    const fileInput = document.getElementById(\'fileInput\'); // \u5047\u8bbe\u6709\u4e00\u4e2a input \u5143\u7d20\u7528\u4e8e\u9009\u62e9\u6587\u4ef6\\r\\n    const selectedFile = fileInput.files[0];\\r\\n    reader.readAsArrayBuffer(selectedFile);\\r\\n```\\r\\n\\r\\n:::caution\\r\\n\u9700\u8981\u6ce8\u610f\u7684\u662f\uff0c\u7531\u4e8e\u6587\u4ef6\u8bfb\u53d6\u662f\u5f02\u6b65\u7684\uff0c\u56e0\u6b64 FileReader \u4f7f\u7528\u4e8b\u4ef6\u5904\u7406\u7a0b\u5e8f\uff08\u4f8b\u5982 onload\uff09\u6765\u6355\u83b7\u8bfb\u53d6\u5b8c\u6210\u540e\u7684\u7ed3\u679c\u3002\\r\\n:::"},{"id":"js/format-types","metadata":{"permalink":"/blog/js/format-types","source":"@site/blog/JS\u7684\u683c\u5f0f\u7c7b\u578b.md","title":"JavaScript\u7684\u4e0d\u540c\u683c\u5f0f\u7c7b\u578b","description":"\u53c2\u8003\uff1ahttps://betterprogramming.pub/what-are-cjs-amd-umd-esm-system-and-iife-3633a112db62","date":"2023-07-22T00:00:00.000Z","formattedDate":"July 22, 2023","tags":[{"label":"UMD","permalink":"/blog/tags/umd"},{"label":"AMD","permalink":"/blog/tags/amd"},{"label":"CJS","permalink":"/blog/tags/cjs"},{"label":"ESModule","permalink":"/blog/tags/es-module"},{"label":"IIFE","permalink":"/blog/tags/iife"}],"readingTime":15.905,"hasTruncateMarker":false,"authors":[{"name":"Allen","url":"https://github.com/ieful","imageURL":"https://avatars.githubusercontent.com/u/138431030?s=96&v=40","key":"Allen"}],"frontMatter":{"slug":"js/format-types","title":"JavaScript\u7684\u4e0d\u540c\u683c\u5f0f\u7c7b\u578b","date":"2023-07-22T00:00:00.000Z","authors":"Allen","tags":["UMD","AMD","CJS","ESModule","IIFE"]},"prevItem":{"title":"\u6587\u4ef6\u7c7b\u578b\u4e4b\u6587\u672c\u6587\u4ef6\u548c\u4e8c\u8fdb\u5236\u6587\u4ef6","permalink":"/blog/\u6587\u672c\u6587\u4ef6\u548c\u4e8c\u8fdb\u5236\u6587\u4ef6"}},"content":"\u53c2\u8003\uff1ahttps://betterprogramming.pub/what-are-cjs-amd-umd-esm-system-and-iife-3633a112db62\\n\\n### \u683c\u5f0f\u7c7b\u578b\\n\\n\u73b0\u4ee3JS\u5f00\u53d1\u4f1a\u88ab\u6253\u5305\u5668\u6253\u5305\ud83d\udce6\u6210\u5404\u79cd\u683c\u5f0f\uff0c\u4e0d\u540c\u7684\u683c\u5f0f\u5206\u522b\u53ef\u4ee5\u8fd0\u884c\u5728\u4e0d\u540c\u7684\u73af\u5883\u4e4b\u4e2d\uff0c\u4e3b\u8981\u7684\u6253\u5305\u683c\u5f0f\u548c\u5176\u9002\u7528\u8303\u56f4\u5982\u4e0b\\n\\n* cjs (CommonJS) \u9002\u7528\u4e8eNode\u73af\u5883\\n* amd (Asynchronous Module Definition ~ \u5f02\u6b65\u6a21\u5757\u5b9a\u4e49)\u9002\u7528\u4e8e\u4f7f\u7528RequireJS\u8fdb\u884c\u6a21\u5757\u52a0\u8f7d\\n* umd (Universal Module Definition ~ \u901a\u7528\u6a21\u5757\u5b9a\u4e49) amd\u3001cjs\u3001iife\u90fd\u652f\u6301\\n* es (ESModule) \u6807\u51c6\u7684es6\u6a21\u5757\u5316\u89c4\u8303\uff0c\u9002\u7528\u4e8e\u652f\u6301es6\u6a21\u5757\u7684\u6253\u5305\u5668\u4ee5\u53ca\u652f\u6301 `<script type=module>` \u7684\u73b0\u4ee3\u6d4f\u89c8\u5668\\n* iife (Immediately Invoked Function Expression) \u81ea\u6267\u884c\u51fd\u6570\u683c\u5f0f\uff0c\u9002\u7528\u4e8e\u76f4\u63a5\u901a\u8fc7 `<script>` \u6807\u7b7e\u5f15\u5165\\n* system SystemJS\u52a0\u8f7d\u5668\u7684\u7684\u672c\u673a\u683c\u5f0f https://github.com/systemjs/systemjs\\n\\n\\n### CommonJS (CJS)\\n\\nCommonJS\u662fNode\u53ca\u5176\u751f\u6001\u73af\u5883\u4e2d\u4f7f\u7528\u7684\u683c\u5f0f\u7c7b\u578b\uff0c\u88ab\u5e7f\u6cdb\u7684\u5e94\u7528\u4e8e\u670d\u52a1\u7aef\u3002CommonJS\u53ef\u4ee5\u901a\u8fc7require()\u65b9\u6cd5\u548cmodule.exports\u547d\u4ee4\u6765\u8bc6\u522b\u3002\\nrequire()\u65b9\u6cd5\u7528\u4e8e\u5bfc\u5165\u4e00\u4e2anode\u6a21\u5757\uff0c\u800cmodule.exports\u662f\u6a21\u5757\u88abrequire()\u65b9\u6cd5\u5bfc\u5165\u65f6\u8fd4\u56de\u7684\u5bf9\u8c61\u3002\\n\\n:::tip\\nCommonJS\u6700\u521d\u5c31\u662f\u8bbe\u8ba1\u7528\u6765\u5728\u670d\u52a1\u7aef\u4f7f\u7528\u7684\uff0c\u6240\u4ee5\u5b83\u7684API\u81ea\u7136\u5730\u90fd\u662f\u540c\u6b65\uff0c\u4e5f\u5c31\u662f\u8bf4CommonJS\u7684\u6a21\u5757\u5bfc\u5165\u987a\u5e8f\u662f\u6309\u4e66\u5199\u987a\u5e8f\u5bfc\u5165\u7684\u3002\\n:::\\n\\n\\n\ud83d\udc47\u4e0b\u9762\u662f\u4e00\u4e2a\u7528roll-up\u751f\u6210\u7684CommonJS\u683c\u5f0f\u7684\u6587\u4ef6\ud83d\udcc3\\n```bash\\n\'use strict\';\\n\\nObject.defineProperty(exports, \'__esModule\', { value: true });\\n\\n/**\\n * Increase the current total value\\n * @param {number} total The current total value\\n * @param {number} value The new value to be added\\n * @returns {number} The new total value\\n */\\nconst increase = (total, value) => total + value;\\n\\n/**\\n * Decrease the current total value\\n * @param {number} total The current total value\\n * @param {number} value The new value to be subtracted\\n * @returns {number} The new total value\\n */\\nconst decrease = (total, value) => total - value;\\n\\nlet others = {\\n  a: 1,\\n  b: 2,\\n  c: () => 3,\\n};\\nconst e = 5;\\n\\n/**\\n * This is the main file\\n */\\n\\nfunction multiply(total, value) {\\n  return total * value;\\n}\\n\\nfunction power(total, value) {\\n  return total ** value;\\n}\\n\\nlet total = others.a;\\n\\ntotal = increase(total, 10);\\ntotal = increase(total, 20);\\ntotal = decrease(total, 5);\\ntotal = multiply(total, e);\\n\\nconsole.log(`Total is ${total}`);\\n\\nexports.power = power;\\n```\\n\ud83d\udc46\u4e0a\u9762\u7684\u6587\u4ef6\u76f4\u63a5\u5728\u6d4f\u89c8\u5668\u4e2d\u6267\u884c\u4f1a\u62a5\u9519 `exports is not defined`\\n\\n:::tip\\n\u53ef\u4ee5\u901a\u8fc7\u6dfb\u52a0\u5982\u4e0b\u4ee3\u7801\u6765\u4fee\u590d\u4e0a\u9762\u7684\u62a5\u9519\\n\\n```bash\\n<script>\\n  const exports = {};\\n<\/script>\\n```\\n\\n:::\\n\\n\\n### UMD\u683c\u5f0f (Universal Module Definition)\\n\\nUMD\u88ab\u8bbe\u8ba1\u65e2\u80fd\u5728\u670d\u52a1\u5668\u7aef\u8fd0\u884c\u4e5f\u80fd\u5728\u6d4f\u89c8\u5668\u4e2d\u8fd0\u884c\uff0c\u5176\u5185\u90e8\u4f7f\u7528AMD\u683c\u5f0f\u4f5c\u4e3a\u57fa\u7840\uff0c\u5e76\u6dfb\u52a0\u4e86\u5f88\u591a\u7279\u6b8a\u7684 `\u5916\u58f3\u4ee3\u7801` \u7528\u6765\u5904\u7406CommonJS\u7684\u517c\u5bb9\u3002\\n\u7136\u800c\uff0c\u517c\u5bb9\u6027\u589e\u52a0\u4e86\u4e00\u4e9b\u590d\u6742\u6027\uff0c\u4e5f\u4f7f\u5f97\u8bfb\u5199\u53d8\u5f97\u590d\u6742\u3002\\n\\n### ESM (ES2015 Module)\\n\u5b98\u65b9\u51fa\u54c1\u7684\u6a21\u5757\u5316\u6807\u51c6\u3002Since the version of ^12.20.0 || ^14.13.1 || >=16.0.0, Node starts to support ESM. ESM gains popularity to be used for both clients and servers.\\n\uff5e Node\u652f\u6301ESM\u540eESM\u8d8a\u6765\u8d8a\u53d7\u6b22\u8fce\ud83d\udc4f\uff0c\u53ef\u4ee5\u540c\u65f6\u5728\u5ba2\u6237\u7aef\u548c\u670d\u52a1\u7aef\u5f00\u53d1\u8fd0\u884c\u3002\\nesm\u7684 `import` \u6307\u4ee4\u53ef\u4ee5\u5c06\u4e00\u4e2aes\u6a21\u5757\u5bfc\u5165\u5f53\u524d\u7684\u4f5c\u7528\u57df\uff0c\u800c\u52a8\u6001\u7684 `import()` \u65b9\u6cd5\u5728ES2020\u6807\u51c6\u4e2d\u652f\u6301; `export` \u6307\u4ee4\u53ef\u4ee5\u5c06\u6a21\u5757\u66b4\u9732\u7ed9\u5176\u4ed6\u6a21\u5757\u4f9b\u5f15\u5165\u3002\\n\\n### IIFE (Immediately Invoked Function Expression)\\n\\n\u81ea\u6267\u884c\u51fd\u6570\u683c\u5f0f\u9002\u7528\u4e8e\u76f4\u63a5\u901a\u8fc7 `<script>` \u6807\u7b7e\u5f15\u5165\u4ee3\u7801\u7684\u65b9\u5f0f\uff0c\u5b83\u5c06\u4ee3\u7801\u653e\u5165\u51fd\u6570\u7684\u547d\u540d\u7a7a\u95f4\u4e2d\u907f\u514d\u4e86\u547d\u540d\u51b2\u7a81\u3002\\n\\n### esm\u548ccjs \u533a\u5206\\n\\n:::tip\\ncjs\u6a21\u5757\u662f\u5bf9\u8c61\uff0c\u8f93\u5165\u65f6\u5fc5\u987b\u67e5\u627e\u5bf9\u8c61\u7684\u5c5e\u6027\uff1besm\u6a21\u5757\u4e0d\u662f\u5bf9\u8c61\uff0c\u800c\u662f\u901a\u8fc7`export\u547d\u4ee4` \u663e\u793a\u5730\u6307\u5b9a\u5bf9\u5916\u8f93\u51fa\u7684\u4ee3\u7801\uff0c\u518d\u901a\u8fc7 `import\u547d\u4ee4` \u8f93\u5165\u3002\\n:::\\n\\n#### \u5148\u6765\u770bcjs\u7684exports\u548cmodule.exports (commonjs\u7684\u65b9\u6cd5exports\u662f\u5e26_s_\u7684\u54e6\uff5e\ud83d\ude1d)\\n\\n\u5728node\u6267\u884c\u4e00\u4e2a\u6587\u4ef6\u7684\u65f6\u5019\uff0c\u4f1a\u81ea\u52a8\u7ed9\u8fd9\u4e2a\u6587\u4ef6\u5185\u751f\u6210\u4e00\u4e2amodule\u5bf9\u8c61\u548c\u4e00\u4e2aexports\u5bf9\u8c61\uff0c\u800cmodule\u5bf9\u8c61\u53c8\u4e00\u4e2aexports\u5c5e\u6027\uff0c\\n\u5b83\u4eec\u4e4b\u95f4\u7684\u5173\u7cfb\u5982\u4e0b\u56fe\uff0c\u9ed8\u8ba4\u90fd\u662f\u6307\u5411\u540c\u4e00\u5757\u5185\u5b58\u7684\uff1a\\n\\n![alt text](/img/exports.png)\\n\u770b\u4ee3\u7801\uff1a\\n\\n```bash\\n//example.js\\nlet a = 100;\\nconsole.log(module.exports); //\u6253\u5370\u51fa\u7ed3\u679c\u4e3a\uff1a{}\\nconsole.log(exports); //\u6253\u5370\u51fa\u7ed3\u679c\u4e3a\uff1a{}\\nconsole.log(exports === module.exports); // \u8f93\u51fa\u7ed3\u679c\u4e3atrue\\n\\nmodule.exports.a = 100;\\n\\nexports.a = 200; // \u8fd9\u91ccexports _\u8f9b\u82e6\u52b3\u4f5c_ \u5e2e module.exports \u5c06\u5c5e\u6027_a_\u7684\u5185\u5bb9\u7ed9\u6539\u6210200\\n\\nexports = \'\u6307\u5411\u5176\u4ed6\u5185\u5b58\u533a\'; // \u6ce8\u610f\u26a0\ufe0f\uff1a\u8fd9\u91cc\u5c06exports\u91cd\u65b0\u8d4b\u503c\u91cc\uff0cexports\u5c06\u4e0d\u518d\u8ddfmodule.exports\u6307\u5411\u540c\u4e00\u5185\u5b58\u533a\u57df\uff0c\u540e\u9762exports\u7684\u4e00\u7cfb\u5217\u5c5e\u6027\u8bbe\u7f6e\u5c06\u4e0d\u518d\u5f71\u54cdmodule.exports\\n...\\n\\n\\n//test.js \\nlet a = require(\'/example\'); // \u5728test.js\u4e2d\u901a\u8fc7 `require()` \u65b9\u6cd5\u5f15\u5165example\\nconsole.log(a) // \u6253\u5370\u4e3a {a : 200}; // \u8bc1\u660e\u5728node\u4e2d `require()` \u65b9\u6cd5\u5f15\u5165\u7684\u5185\u5bb9\u662fmodule.exports\u5bf9\u8c61\u800c\u4e0d\u662fexports!!\\n```\\n:::tip\\nexports\u5bf9\u8c61\u53ea\u662f\u4e3a\u4e86\u8ba9\u4f60\u5728\u7ed9\u6a21\u5757\u5b9a\u4e49\u5c5e\u6027\u7684\u65f6\u5019\uff0c\u53ef\u4ee5\u5c11\u6253\u51e0\u4e2a\u5b57\u6bcd\uff0c\u76f4\u63a5\u7528exports.a = 123, exports.b = 456 ...\u5c31\u884c\u4e86\u4e0d\u7528\u9ebb\u70e6\u7684\u5e26\u7740module.exports.a = xxxx\\n\u4f46\u662f\u5343\u4e07\u4e0d\u8981\u628aexports\u76f4\u63a5\u8d4b\u503c\u7ed9\u5176\u4ed6\u503c\u54e6\uff5e \u4e00\u65e6\u5199\u4e86 exports = xxx exports\u548c module.exports\u4e4b\u95f4\u7684\u8054\u7cfb\u5c31\u65ad\u4e86\uff5e\\n:::\\n\\n#### \u518d\u770besm\u7684export\u3001import\u548cexport default (esm\u7684export\u662f\u4e0d\u5e26_s_\u7684\u5462\uff5e\ud83d\ude09)\\nesm\u7684\u6a21\u5757\u529f\u80fd\u4e3b\u8981\u7531\u4e24\u4e2a\u547d\u4ee4\u7ec4\u6210\uff1a`export` \u548c `import`\\n\\n##### export\\n\\n:::info\\n\u518d\u6b21\u63d0\u9192\uff0cesm\u4e2d\u7684 `export` \u548c `import` \u662f\u547d\u4ee4(\u6216\u8005\u53eb\u5173\u952e\u5b57\ud83d\ude1d)\u4e0d\u662f\u65b9\u6cd5\u3002\\n:::\\n\\nexport\u547d\u4ee4\u7528\u4e8e\u89c4\u5b9a\u6a21\u5757\u7684\u5bf9\u5916\u63a5\u53e3\uff0cimport\u547d\u4ee4\u7528\u4e8e\u8f93\u5165\u5176\u4ed6\u6a21\u5757\u63d0\u4f9b\u7684\u529f\u80fd\u3002\u5728esm\u4e2d\u4e00\u4e2a\u6587\u4ef6\u5c31\u662f\u4e00\u4e2a\u72ec\u7acb\u7684\u6a21\u5757\uff0c\u5728\u6587\u4ef6\u6a21\u5757\u5185\u90e8\u6240\u6709\u7684\u53d8\u91cf\uff0c\u5916\u90e8\\n\u662f\u65e0\u6cd5\u83b7\u53d6\u7684\uff0c\u5982\u679c\u5e0c\u671b\u5916\u90e8\u80fd\u591f\u8bfb\u53d6\u5185\u90e8\u7684\u67d0\u4e2a\u53d8\u91cf\uff0c\u5c31\u5fc5\u987b\u663e\u793a\u7684\u4f7f\u7528 `export` \u5173\u952e\u5b57\u8f93\u51fa\u8be5\u53d8\u91cf\u3002\\n\u53ef\u4ee5\u5411\u4e0b\u9762\u8fd9\u6837\ud83d\udc47\\n\\n\u5199\u6cd5\u4e00\uff1a\u7528\u4e09\u4e2aexport\u547d\u4ee4\u5bf9\u5916\u8f93\u51fa\u4e09\u4e2a\u53d8\u91cf\\n```bash\\n// profile.js \\nexport let firstName = \'Michael\';\\nexport let lastName = \'Jackson\';\\nexport let year = 1958;\\n```\\n\\n\u5199\u6cd5\u4e8c\uff1a\u4f7f\u7528\u5927\u62ec\u53f7\u6307\u5b9a\u6240\u8981\u8f93\u51fa\u7684\u4e00\u7ec4\u53d8\u91cf\ud83d\udc4d\\n```bash\\n// profile.js \\nlet firstName = \'Michael\';\\nlet lastName = \'Jackson\';\\nlet year = 1958;\\nexport {firstName, lastName, year};\\n```\\n:::tip\\n\u7b2c\u4e8c\u79cd\u4e0e\u524d\u4e00\u79cd\u5199\u6cd5\uff08\u76f4\u63a5\u653e\u7f6e\u5728let\u8bed\u53e5\u524d\uff09\u662f\u7b49\u4ef7\u7684\uff0c\u4f46\u662f\u5e94\u8be5\u4f18\u5148\u8003\u8651\u4f7f\u7528\u8fd9\u79cd\u5199\u6cd5\u3002\u56e0\u4e3a\u8fd9\u6837\u5c31\u53ef\u4ee5\u5728\u811a\u672c\u5c3e\u90e8\uff0c\u4e00\u773c\u770b\u6e05\u695a\u8f93\u51fa\u4e86\u54ea\u4e9b\u53d8\u91cf\u3002\\n:::\\n\\n\u901a\u5e38\u60c5\u51b5\u4e0b\uff0cexport\u8f93\u51fa\u7684\u53d8\u91cf\u5c31\u662f\u672c\u6765\u7684\u540d\u5b57\uff0c\u4f46\u662f\u53ef\u4ee5\u4f7f\u7528as\u5173\u952e\u5b57\u91cd\u547d\u540d\u3002\u50cf\u4e0b\u9762\u8fd9\u6837\ud83d\udc47\\n\\n```bash\\nfunction v1() { ... }\\nfunction v2() { ... }\\n\\nexport {\\n  v1 as streamV1,\\n  v2 as streamV2,\\n  v2 as streamLatestVersion\\n};\\n```\\n\\n:::caution\\n\u9700\u8981\u7279\u522b\u6ce8\u610f\u7684\u662f\uff0cexport\u547d\u4ee4\u89c4\u5b9a\u7684\u662f\u5bf9\u5916\u7684\u63a5\u53e3\uff0c\u5fc5\u987b\u4e0e\u6a21\u5757\u5185\u90e8\u7684\u53d8\u91cf\u5efa\u7acb\u4e00\u4e00\u5bf9\u5e94\u5173\u7cfb\u3002\\n:::\\n\\n\ud83d\udc47\u4e0b\u9762\u7684\u4e24\u79cd\u5199\u6cd5\u90fd\u662f\u9519\u7684\u274c\\n```bash\\n// \u62a5\u9519\\nexport 1;\\n\\n// \u62a5\u9519\\nlet m = 1;\\nexport m;\\n```\\n\\n\u4e0a\u9762\u4e24\u79cd\u5199\u6cd5\u90fd\u4f1a\u62a5\u9519\uff0c\u56e0\u4e3a\u6ca1\u6709\u63d0\u4f9b\u5bf9\u5916\u7684\u63a5\u53e3\u3002\u7b2c\u4e00\u79cd\u5199\u6cd5\u76f4\u63a5\u8f93\u51fa 1\uff0c\u7b2c\u4e8c\u79cd\u5199\u6cd5\u901a\u8fc7\u53d8\u91cfm\uff0c\u8fd8\u662f\u76f4\u63a5\u8f93\u51fa 1\u30021\u53ea\u662f\u4e00\u4e2a\u503c\uff0c\u4e0d\u662f\u63a5\u53e3\u3002\u6b63\u786e\u7684\u5199\u6cd5\u662f\u4e0b\u9762\u8fd9\u6837\u3002\\n\\n```bash\\n// \u5199\u6cd5\u4e00\\nexport let m = 1;\\n\\n// \u5199\u6cd5\u4e8c\\nlet m = 1;\\nexport {m};\\n\\n// \u5199\u6cd5\u4e09\\nlet n = 1;\\nexport {n as m};\\n```\\n\u4e0a\u9762\u4e09\u79cd\u5199\u6cd5\u90fd\u662f\u6b63\u786e\u7684\uff0c\u89c4\u5b9a\u4e86\u5bf9\u5916\u7684\u63a5\u53e3m\u3002\u5176\u4ed6\u811a\u672c\u53ef\u4ee5\u901a\u8fc7\u8fd9\u4e2a\u63a5\u53e3\uff0c\u53d6\u5230\u503c1\u3002\u5b83\u4eec\u7684\u5b9e\u8d28\u662f\uff0c\u5728\u63a5\u53e3\u540d\u4e0e\u6a21\u5757\u5185\u90e8\u53d8\u91cf\u4e4b\u95f4\uff0c\u5efa\u7acb\u4e86\u4e00\u4e00\u5bf9\u5e94\u7684\u5173\u7cfb\u3002\\n\\n\u540c\u6837\u7684\uff0cfunction\u548cclass\u7684\u8f93\u51fa\uff0c\u4e5f\u5fc5\u987b\u9075\u5b88\u8fd9\u6837\u7684\u5199\u6cd5\u3002\\n\\n\u76ee\u524d\uff0cexport \u547d\u4ee4\u80fd\u591f\u5bf9\u5916\u8f93\u51fa\u7684\u5c31\u662f\u4e09\u79cd\u63a5\u53e3\uff1a\u51fd\u6570\uff08Functions\uff09\uff0c \u7c7b\uff08Classes\uff09\uff0cvar\u3001let\u3001const \u58f0\u660e\u7684\u53d8\u91cf\uff08Variables\uff09\u3002\\n\\n\u53e6\u5916\uff0cexport\u8bed\u53e5\u8f93\u51fa\u7684\u63a5\u53e3\uff0c\u4e0e\u5176\u5bf9\u5e94\u7684\u503c\u662f\u52a8\u6001\u7ed1\u5b9a\u5173\u7cfb\uff0c\u5373\u901a\u8fc7\u8be5\u63a5\u53e3\uff0c\u53ef\u4ee5\u53d6\u5230\u6a21\u5757\u5185\u90e8\u5b9e\u65f6\u7684\u503c\u3002\\n\\n```bash\\nexport let foo = \'bar\';\\nsetTimeout(() => foo = \'baz\', 500);\\n```\\n\u4e0a\u9762\u4ee3\u7801\u8f93\u51fa\u53d8\u91cffoo\uff0c\u503c\u4e3abar\uff0c500 \u6beb\u79d2\u4e4b\u540e\u53d8\u6210baz\u3002\\n\\n\u8fd9\u4e00\u70b9\u4e0e CommonJS \u89c4\u8303\u5b8c\u5168\u4e0d\u540c\u3002CommonJS \u6a21\u5757\u8f93\u51fa\u7684\u662f\u503c\u7684\u7f13\u5b58\uff0c\u4e0d\u5b58\u5728\u52a8\u6001\u66f4\u65b0.\\n\\n##### import\\n\u4f7f\u7528export\u547d\u4ee4\u5b9a\u4e49\u4e86\u6a21\u5757\u7684\u5bf9\u5916\u63a5\u53e3\u4ee5\u540e\uff0c\u5176\u4ed6 JS \u6587\u4ef6\u5c31\u53ef\u4ee5\u901a\u8fc7import\u547d\u4ee4\u52a0\u8f7d\u8fd9\u4e2a\u6a21\u5757\\n\\n```bash\\n// main.js\\nimport { firstName, lastName, year } from \'./profile.js\';\\n\\nfunction setName(element) {\\n  element.textContent = firstName + \' \' + lastName;\\n}\\n```\\n\u4e0a\u9762\u4ee3\u7801\u7684import\u547d\u4ee4\uff0c\u7528\u4e8e\u52a0\u8f7dprofile.js\u6587\u4ef6\uff0c\u5e76\u4ece\u4e2d\u8f93\u5165\u53d8\u91cf\u3002**import\u547d\u4ee4\u63a5\u53d7\u4e00\u5bf9\u5927\u62ec\u53f7**\uff0c\u91cc\u9762\u6307\u5b9a\u8981\u4ece\u5176\u4ed6\u6a21\u5757\u5bfc\u5165\u7684\u53d8\u91cf\u540d\u3002\u5927\u62ec\u53f7\u91cc\u9762\u7684\u53d8\u91cf\u540d\uff0c\u5fc5\u987b\u4e0e\u88ab\u5bfc\u5165\u6a21\u5757\uff08profile.js\uff09\u5bf9\u5916\u63a5\u53e3\u7684\u540d\u79f0\u76f8\u540c\u3002\\n\\n:::caution\\nimport\u547d\u4ee4\u8f93\u5165\u7684\u53d8\u91cf\u90fd\u662f\u53ea\u8bfb\u7684\uff0c\u56e0\u4e3a\u5b83\u7684\u672c\u8d28\u662f\u8f93\u5165\u63a5\u53e3\u3002\u4e5f\u5c31\u662f\u8bf4\uff0c\u4e0d\u5141\u8bb8\u5728\u52a0\u8f7d\u6a21\u5757\u7684\u811a\u672c\u91cc\u9762\uff0c\u6539\u5199\u63a5\u53e3\u3002\\n:::\\n\\n```bash\\nimport {a} from \'./xxx.js\'\\n\\na = {}; // Syntax Error : \'a\' is read-only;\\n```\\n\u4e0a\u9762\u4ee3\u7801\u4e2d\uff0c\u811a\u672c\u52a0\u8f7d\u4e86\u53d8\u91cfa\uff0c\u5bf9\u5176\u91cd\u65b0\u8d4b\u503c\u5c31\u4f1a\u62a5\u9519\uff0c\u56e0\u4e3aa\u662f\u4e00\u4e2a\u53ea\u8bfb\u7684\u63a5\u53e3\u3002\u4f46\u662f\uff0c\u5982\u679ca\u662f\u4e00\u4e2a\u5bf9\u8c61\uff0c\u6539\u5199a\u7684\u5c5e\u6027\u662f\u5141\u8bb8\u7684\u3002\\n\\n```bash\\nimport {a} from \'./xxx.js\'\\n\\na.foo = \'hello\'; // \u5408\u6cd5\u64cd\u4f5c\\n```\\n:::info\\n\u4e0a\u9762\u4ee3\u7801\u4e2d\uff0ca\u7684\u5c5e\u6027\u53ef\u4ee5\u6210\u529f\u6539\u5199\uff0c\u5e76\u4e14\u5176\u4ed6\u6a21\u5757\u4e5f\u53ef\u4ee5\u8bfb\u5230\u6539\u5199\u540e\u7684\u503c\u3002\u4e0d\u8fc7\uff0c\u8fd9\u79cd\u5199\u6cd5\u5f88\u96be\u67e5\u9519\uff0c\u5efa\u8bae\u51e1\u662f\u8f93\u5165\u7684\u53d8\u91cf\uff0c\u90fd\u5f53\u4f5c\u5b8c\u5168\u53ea\u8bfb\uff0c\u4e0d\u8981\u8f7b\u6613\u6539\u53d8\u5b83\u7684\u5c5e\u6027\u3002\\n:::\\n\\n:::tip\\nimport\u8bed\u53e5\u4f1a\u6267\u884c\u6240\u52a0\u8f7d\u7684\u6a21\u5757\uff0c\u56e0\u6b64\u53ef\u4ee5\u6709\u4e0b\u9762\u7684\u5199\u6cd5\u3002\\n:::\\n\\n```bash\\nimport \'lodash\';\\n```\\n***\u4e0a\u9762\u4ee3\u7801\u4ec5\u4ec5\u6267\u884clodash\u6a21\u5757\uff0c\u4f46\u662f\u4e0d\u8f93\u5165\u4efb\u4f55\u503c***\u3002\\n\\n:::caution\\n\u6ce8\u610f\u26a0\ufe0f:\u4e0a\u9762\u8fd9\u79cd\u60c5\u51b5\u5f88\u591a\u4eba\u5206\u4e0d\u6e05\uff0c\u7f51\u4e0a\u4e5f\u5f88\u591a\u4eba\u7406\u89e3\u6210 export default\u7684\u60c5\u51b5\uff0c`import \'lodash` \u548c `import lodash from \'lodash\'` \u3001`import _ from \'lodash\'`\\n\u662f\u5b8c\u5168\u4e0d\u540c\u7684\u610f\u601d\uff0c\u540e\u8005\u5f88\u597d\u7406\u89e3\uff0c\u5c31\u662f\u5c06lodash\u5e93\u5f15\u5165\u8fdb\u6765\u5e76\u8d4b\u503c\u4e3a`lodash` `_` \u53d8\u91cf\uff0c\u800c `import \'lodash` \u4ec5\u4ec5\u53ea\u662f\u6267\u884c\u4e86loadash\u6a21\u5757\uff0c\u5e76\u6ca1\u6709\u8f93\u5165\u4efb\u4f55\u503c\uff01\\n\u7f51\u4e0a\u8fd9\u91cc\u6709\u4e2a\u4f8b\u5b50: https://segmentfault.com/q/1010000006229052\\n![alt text](/img/meteor.png)\\n\u548c css \u91cc @import xxx.css \u7c7b\u4f3c\u7684\u529f\u80fd\uff0c`import lodash` \u53ea\u662f\u628a lodash \u8fd9\u4e2a\u6a21\u5757\u5f53\u505a\u9759\u6001\u6587\u4ef6\u5728\u7f16\u8bd1\u9636\u6bb5\u5f15\u5165\u800c\u5df2\u3002\u3002\u3002\u3002\\n\u53e6\uff1aES6 \u60f3\u8981 import \u4e00\u4e2a\u6a21\u5757\u4e2d\u7684\u53d8\u91cf\u7b49\u5185\u5bb9\u5fc5\u987b\u5bf9\u5176\u505a\u6a21\u5757\u89e3\u6784\uff0c\u5426\u5219\u53ea\u4f1a\u6267\u884c\u4ee3\u7801\u800c\u6ca1\u6709\u4efb\u4f55\u5bfc\u5165\u7684\u5185\u5bb9\u3002\u8fd9\u4e2a\u9053\u7406\u8ddf Node.js \u4e2d\u7684\u6a21\u5757\u6ca1\u6709 export \u5185\u5bb9\u5c31 require \u5c31\u53ea\u4f1a\u6267\u884c\u4ee3\u7801\u4e0d\u4f1a\u5bfc\u5165\u5185\u5bb9\u662f\u4e00\u4e2a\u9053\u7406\\n:::\\n\\n\u76ee\u524d\u9636\u6bb5\uff0c\u901a\u8fc7 Babel \u8f6c\u7801\uff0cCommonJS \u6a21\u5757\u7684require\u547d\u4ee4\u548c ES6 \u6a21\u5757\u7684import\u547d\u4ee4\uff0c\u53ef\u4ee5\u5199\u5728\u540c\u4e00\u4e2a\u6a21\u5757\u91cc\u9762\uff0c\u4f46\u662f\u6700\u597d\u4e0d\u8981\u8fd9\u6837\u505a\u3002\u56e0\u4e3aimport\u5728\u9759\u6001\u89e3\u6790\u9636\u6bb5\u6267\u884c\uff0c\u6240\u4ee5\u5b83\u662f\u4e00\u4e2a\u6a21\u5757\u4e4b\u4e2d\u6700\u65e9\u6267\u884c\u7684\u3002\u4e0b\u9762\u7684\u4ee3\u7801\u53ef\u80fd\u4e0d\u4f1a\u5f97\u5230\u9884\u671f\u7ed3\u679c\u3002\\n\\n```bash\\nrequire(\'core-js/modules/es6.symbol\');\\nrequire(\'core-js/modules/es6.promise\');\\nimport React from \'React\';\\n```\\n\\n##### export default\u547d\u4ee4\\n\u4f7f\u7528import\u547d\u4ee4\u7684\u65f6\u5019\uff0c\u7528\u6237\u9700\u8981\u77e5\u9053\u6240\u8981\u52a0\u8f7d\u7684\u53d8\u91cf\u540d\u6216\u51fd\u6570\u540d\uff0c\u5426\u5219\u65e0\u6cd5\u52a0\u8f7d\u3002\u4f46\u662f\uff0c\u7528\u6237\u80af\u5b9a\u5e0c\u671b\u5feb\u901f\u4e0a\u624b\uff0c\u672a\u5fc5\u613f\u610f\u9605\u8bfb\u6587\u6863\uff0c\u53bb\u4e86\u89e3\u6a21\u5757\u6709\u54ea\u4e9b\u5c5e\u6027\u548c\u65b9\u6cd5\u3002\\n\u4e3a\u4e86\u7ed9\u7528\u6237\u63d0\u4f9b\u65b9\u4fbf\uff0c\u8ba9\u4ed6\u4eec\u4e0d\u7528\u9605\u8bfb\u6587\u6863\u5c31\u80fd\u52a0\u8f7d\u6a21\u5757\uff0c\u5c31\u8981\u7528\u5230export default\u547d\u4ee4\uff0c\u4e3a\u6a21\u5757\u6307\u5b9a\u9ed8\u8ba4\u8f93\u51fa\u3002\\n\\n```bash\\n// export-default.js\\nexport default function () {\\n  console.log(\'foo\');\\n}\\n```\\n\u4e0a\u9762\u4ee3\u7801\u662f\u4e00\u4e2a\u6a21\u5757\u6587\u4ef6export-default.js\uff0c\u5b83\u7684\u9ed8\u8ba4\u8f93\u51fa\u662f\u4e00\u4e2a\u51fd\u6570\u3002\\n\\n\u5176\u4ed6\u6a21\u5757\u52a0\u8f7d\u8be5\u6a21\u5757\u65f6\uff0cimport\u547d\u4ee4\u53ef\u4ee5\u4e3a\u8be5\u533f\u540d\u51fd\u6570\u6307\u5b9a\u4efb\u610f\u540d\u5b57\u3002\\n\\n```bash\\n// import-default.js\\nimport customName from \'./export-default\';\\ncustomName(); // \'foo\'\\n```\\n\u4e0a\u9762\u4ee3\u7801\u7684import\u547d\u4ee4\uff0c\u53ef\u4ee5\u7528\u4efb\u610f\u540d\u79f0\u6307\u5411export-default.js\u8f93\u51fa\u7684\u65b9\u6cd5\uff0c\u8fd9\u65f6\u5c31\u4e0d\u9700\u8981\u77e5\u9053\u539f\u6a21\u5757\u8f93\u51fa\u7684\u51fd\u6570\u540d\u3002**\u9700\u8981\u6ce8\u610f\u7684\u662f\uff0c\u8fd9\u65f6import\u547d\u4ee4\u540e\u9762\uff0c\u4e0d\u4f7f\u7528\u5927\u62ec\u53f7**\u3002\\n:::tip\\n\u4e0a\u4e00\u8282\u7684\u6700\u540e\u4e00\u4e2a\u4f8b\u5b50\u4e2d\\n\\n```bash\\nimport React from \'React\';  \\n```\\n\\n`import React` \u6ca1\u6709\u4f7f\u7528\u6253\u62ec\u53f7\uff0c\u5c31\u662f\u56e0\u4e3aReact\u5e93\u5185\u90e8\u4f7f\u7528 `export default` \u6307\u5b9a\u4e86\u9ed8\u8ba4\u5bfc\u51fa\u63a5\u53e3\u3002\\n:::\\n\\n`export default` \u547d\u4ee4\u7528\u4e8e\u6307\u5b9a\u6a21\u5757\u7684\u9ed8\u8ba4\u8f93\u51fa\u3002\u663e\u7136\uff0c\u4e00\u4e2a\u6a21\u5757\u53ea\u80fd\u6709\u4e00\u4e2a\u9ed8\u8ba4\u8f93\u51fa\uff0c\u56e0\u6b64export default\u547d\u4ee4\u53ea\u80fd\u4f7f\u7528\u4e00\u6b21\u3002\u6240\u4ee5\uff0cimport\u547d\u4ee4\u540e\u9762\u624d\u4e0d\u7528\u52a0\u5927\u62ec\u53f7\uff0c\u56e0\u4e3a\u53ea\u53ef\u80fd\u552f\u4e00\u5bf9\u5e94export default\u547d\u4ee4\u3002\\n\\n\u672c\u8d28\u4e0a\uff0c`export default` \u5c31\u662f\u8f93\u51fa\u4e00\u4e2a\u53eb\u505adefault\u7684\u53d8\u91cf\u6216\u65b9\u6cd5\uff0c\u7136\u540e\u7cfb\u7edf\u5141\u8bb8\u4f60\u4e3a\u5b83\u53d6\u4efb\u610f\u540d\u5b57\u3002\u6240\u4ee5\uff0c\u4e0b\u9762\u7684\u5199\u6cd5\u662f\u6709\u6548\u7684\u3002\\n\\n```bash\\n// modules.js\\nfunction add(x, y) {\\n  return x * y;\\n}\\nexport {add as default};\\n// \u7b49\u540c\u4e8e\\n// export default add;\\n\\n// app.js\\nimport { default as foo } from \'modules\';\\n// \u7b49\u540c\u4e8e\\n// import foo from \'modules\';\\n```\\n\\n\u6709\u4e86export default\u547d\u4ee4\uff0c\u8f93\u5165\u6a21\u5757\u65f6\u5c31\u975e\u5e38\u76f4\u89c2\u4e86\uff0c\u4ee5\u8f93\u5165 lodash \u6a21\u5757\u4e3a\u4f8b\u3002\\n\\n```bash\\nimport _ from \'lodash\';\\n```\\n\\n\u5982\u679c\u60f3\u5728\u4e00\u6761import\u8bed\u53e5\u4e2d\uff0c\u540c\u65f6\u8f93\u5165\u9ed8\u8ba4\u65b9\u6cd5\u548c\u5176\u4ed6\u63a5\u53e3\uff0c\u53ef\u4ee5\u5199\u6210\u4e0b\u9762\u8fd9\u6837\u3002\\n\\n```bash\\nimport _, { each, forEach } from \'lodash\';\\n```\\n\u5bf9\u5e94\u4e0a\u9762\u4ee3\u7801\u7684export\u8bed\u53e5\u5982\u4e0b:\\n\\n```bash\\nexport default function (obj) {\\n  // \xb7\xb7\xb7\\n}\\n\\nexport function each(obj, iterator, context) {\\n  // \xb7\xb7\xb7\\n}\\n\\nexport { each as forEach };\\n```"}]}')}}]);